import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchBF: [CaseTemplate] = [coachRecruitBribes, neverHeldFestival, falseTeamAccusation, deviceOnDeliveryDriver, lotteryClerkInsider, mugshotRemovalFees, laneClosurePayback, neighborsWatchStabbing, unneededSurgeries, phantomPatientClaims, tornadoReliefKept, slowCarHoodClaims, localCelebrityTracker, syrupReserveHeist, reptileHoardCruelty, brotherNameForTwentyYears, droneDropAtTheYard, riggedMidwayGame, santaSuitIntruder, fortyDollarBankNote, stormLootingCrew, vacationRentalNoHouse, fairgroundSwingFall, campgroundBluegrassBrawl, horseShowTreasurer, moonshineRunCrash, wrongHouseShot, nursingHomeNightShift, kittenFoodBurglars, grandchildCallerScheme, bakeryInsuranceBlaze, fentanylSalineSwap, clinicWithoutLicense, fakeIllnessFundraiser, golfPartnerTips, mowerOnTheBypass, buriedCoinDig, harborMonsterHoax, cheeseTruckTheft, goatInTheSanctuary, gardenGnomeHeist, creamPieSmash, mascotNappingCase, giantPumpkinSmash, spotlightHunt, electionSignSabotage, oysterBedPoach, rodeoClownShove, plowChaseLot, pranksterBalloonCall]

    static let coachRecruitBribes = SmallCases.make(
        key: "story.coachRecruitBribes",
        category: .whiteCollar,
        headlines: ["College Coach Took Cash to List Non-Athletes as Recruits", "Admissions Office Notices Empty Rosters"],
        law: "bribery",
        threshold: 8,
        spec: "Corruptly accepted a thing of value as a public official, on or about {DATE}.",
        ages: 28...60,
        victim: false,
        summary: "{D}, a state college tennis coach, took $60,000 from parents on {DATE} to list their children as recruited athletes, though none played. A consultant wore a recorder. {DL} says the money was donations to the program.",
        state: [E(.video, 3, "Consultant Recording", "{D} agrees a price per 'recruit.'"), E(.document, 3, "Admissions Lists", "Four recruits who never joined the team."), E(.document, 2, "Program Account", "$60,000 deposited, $9,000 spent on the team.")],
        defense: [E(.document, 1, "Donation Letters", "Letters thanking donors.")],
        role: "Admissions officer",
        exam: [.direct("What did you find in the admissions lists?", "\"Four recruited athletes for the tennis program who never joined the team. {D} had listed them as recruits for money.\""), .direct("What does the consultant's recording show?", "\"It shows {DL} agreeing on a price per recruit. The consultant wore a recorder, and the recording captures the deal.\""), .direct("What do the program account records show?", "\"$60,000 deposited, and only $9,000 spent on the team. The rest is unaccounted for.\""), .direct("How do tennis recruits normally come to your office?", "\"The coach submits a roster with high school records, rankings, and film. We verify the athlete's record before approving a recruited spot.\""), .direct("What did you find unusual?", "\"Four names with no tennis records at all, no tournament results, and no film. They were later admitted under the athlete category.\""), .direct("How did the investigation proceed?", "\"A consultant came to us with concerns and agreed to wear a recorder. On the tape, the coach quotes a price for each name.\""), .cross("{DL} says the money was donations to the program, doesn't {D.he}?", "\"There are letters thanking donors. But recruits listed for money are not donors.\""), .cross("Did the parents get what they paid for?", "\"Their children were listed as recruited athletes. Whether that helped admissions is for the school to decide.\""), .cross("Did any recruit play?", "\"None of the four. They never joined. That's what the roster shows.\""), .cross("Donations to athletic programs are allowed, aren't they?", "\"Yes, with proper channels. They do not buy a roster spot.\""), .cross("The program account did get the money, didn't it?", "\"$60,000 was deposited, and $9,000 of it went to the court fund. I traced the rest in the audit.\"")],
        defenseRole: "Assistant coach",
        defenseExam: [.direct("What is your role with {D}?", "\"I am the assistant coach and run practice most days. I have worked with {D} for six years.\""), .direct("How is the team run?", "\"We have about twenty players, drills every afternoon, and matches on weekends. Recruits join in the fall.\""), .direct("Did the four named students ever show up?", "\"No. I never saw them on the court, at practice, or in a match.\""), .direct("What did the defendant say about those names?", "\"That they were supporters of the program and would join if they could. I did not ask more.\""), .direct("Did you know about money from parents?", "\"Not until the investigation. I thought donations went to the booster fund, not to {D.him}.\""), .direct("What did you think when you heard?", "\"I was stunned. I had seen thank-you letters but never anything about payments for roster spots.\""), .cross("Roster spots are meant for players, aren't they?", "\"Yes. A spot should go to someone who plays.\""), .cross("You never saw those four in a uniform, did you?", "\"Never. They were not on the court even once.\""), .cross("You would have noticed four new players, wouldn't you?", "\"Yes. A roster is small, and everyone stands out.\""), .cross("You did not check the admissions lists, did you?", "\"No. That is the coach's job and the school's.\""), .cross("{D} never told you about prices, did {D.he}?", "\"No. I would have objected.\"")],
        theory: ("{D} sold roster spots.", "Donations."),
        allocution: "\"I let it get out of hand.\"",
        truths: ("{DL} bought a lake lot with part of it.", "The program's court fund really received $9,000."),
        defendant: [.direct("Where did the $60,000 go?", "\"Into the program account. I considered it donations from parents who wanted to support tennis. I spent some on the team.\""), .direct("Did you list the children as recruits for pay?", "\"I listed them because the parents were supporters. I didn't promise admission. I should have kept the two things apart.\""), .direct("Did you intend to cheat the school?", "\"No. I thought of the money as gifts. I never meant to deceive admissions, and I wasn't paid personally.\""), .direct("How do you run your program?", "\"I coach about twenty players with a small budget. I fund-raise every year to keep the courts in shape.\""), .direct("What did you tell parents?", "\"That gifts to the program helped with equipment and that their children would be welcome around the team. I did not promise play.\""), .direct("How did you use the money?", "\"Part went into the court fund, and part went toward expenses I had personally paid for the program. I bought a lake lot with some of it.\""), .cross("You agreed on a price per recruit on the recording, didn't you?", "\"Yes. I did talk about numbers. It sounded worse than I meant. I understand how it looks.\""), .cross("None of those four ever played, did they?", "\"No. They didn't. I knew that when I listed them.\""), .cross("Only $9,000 went to the team, didn't it?", "\"That's what the records say. The rest was used for program costs I didn't track well.\""), .cross("You named a price for each name on tape, didn't you?", "\"I used numbers, and I know the recording makes it sound like a price.\""), .cross("You filed those four as recruits, didn't you?", "\"Yes. I should not have, because none ever played.\"")],
        openings: ("{D}, a state college tennis coach, took $60,000 from parents to list their children as recruited athletes, though none ever played. A consultant's recording captures the price per recruit. The State will present the admissions officer and the records.", "The defense will present donations to a program, thank-you letters, and a coach who never promised admission and was not paid personally. Listen closely to the witnesses."),
        closings: ("Four recruits who never played, a price per recruit on tape, and $60,000 that barely reached the team. Admissions depends on honest lists.", "Donations to a program are not bribes. {D} thanked donors and spent on the team. The State has not proved {D} sold admission."),
        timeline: [(-60, "The consultant approaches {DL}."), (0, "The cash changes hands."), (30, "Lists are filed."), (90, "The audit.")],
        identified: "A recording.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let neverHeldFestival = SmallCases.make(
        key: "story.neverHeldFestival",
        category: .whiteCollar,
        headlines: ["Promoter Sold 2,000 Tickets to a Luxury Beach Festival That Was Never Built", "Guests Stranded With Tents and Wristbands"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and others, in the weeks before {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a promoter, sold 2,000 tickets worth $410,000 in the weeks before the festival date of {DATE} for a luxury coast festival with chefs and stages. Nothing was built. Guests arrived to an empty field on {DATE}. {DL} says funding fell through.",
        state: [E(.digital, 3, "Ticket Sales", "$410,000 in six weeks."), E(.digital, 3, "Marketing Posts", "Photos of stages that did not exist."), E(.document, 2, "Bank Records", "Funds moved to {D}'s accounts.")],
        defense: [E(.document, 1, "Investor Emails", "Emails seeking investors.")],
        role: "Ticket buyer",
        exam: [.direct("What did you buy from {D}?", "\"A ticket to a luxury coast festival with chefs and stages. I paid for it weeks ahead, along with about 2,000 other buyers.\""), .direct("What did you find when you arrived?", "\"An empty field. Nothing had been built, no stages, no tents, no chefs, and no staff to tell us anything.\""), .direct("What had the marketing posts shown?", "\"Photos of stages and a beautiful setting. We later learned the stages in those photos did not exist.\""), .direct("How did you hear about the festival?", "\"An ad on social media promised chefs, bands, and a beachfront stage over three days. I bought two tickets for $400 each.\""), .direct("What preparations did you make?", "\"I booked a hotel, paid for a rental car, and took time off work. Several friends did the same.\""), .direct("What did you see when you arrived?", "\"A grass field with a small rope at the entrance and one porta-potty. A sign said the festival was canceled, and people were crying.\""), .cross("{D} says funding fell through, doesn't {D.he}?", "\"Yes. I have heard that said. But the bank records show money moved to {D}'s own accounts.\""), .cross("Did {D} make any effort to hold the event?", "\"I do not know. I saw no sign of one on the festival date, and no refunds came after.\""), .cross("Were refunds ever offered?", "\"No. I was never refunded. Many of us were out our whole ticket price.\""), .cross("The festival site was a rented field, wasn't it?", "\"I believe so. Nobody told me whether the rental was paid for.\""), .cross("You do not know where the money went, do you?", "\"Only what the bank records show. They show transfers to {DL}'s accounts.\"")],
        defenseRole: "Investor",
        defenseExam: [.direct("Did {D} seek funding for the festival?", "\"Yes. {D} sent me emails and made calls to many investors, trying hard to raise the money needed.\""), .direct("Did the funding arrive?", "\"No. I did not invest, and as far as I know no one else did either. The deals fell through.\""), .direct("How did the defendant describe the plan to you?", "\"As a real event with a real site. {D.He} sounded committed, and I believed it was a serious attempt.\""), .direct("How did you come to know the defendant?", "\"I run a small fund and {D.he} approached me for an investment in the festival. We met three times and exchanged emails.\""), .direct("What did the defendant show you?", "\"A budget, a site plan, and renderings of the stages. It looked professional.\""), .direct("What did you decide?", "\"I wanted to invest but needed proof of permits and vendor contracts first. They never came.\""), .cross("Did you personally see any stages built or any vendors hired?", "\"No. I never saw a stage or a signed vendor. I only saw the plan on paper.\""), .cross("Did the defendant tell you tickets were already on sale before funding was secure?", "\"I understood tickets were on sale. I did not know how much had been taken in.\""), .cross("Did you hear about a rented villa paid for with ticket money?", "\"Not until later. I would not have discussed investing had I known about that.\""), .cross("You did not see any signed contracts, did you?", "\"No, only drafts and promises.\""), .cross("{D} was selling tickets at the same time, wasn't {D.he}?", "\"Yes, and I was uneasy about that. I told {D.him} to hold off until funding was set.\"")],
        theory: ("{D} sold a festival that did not exist.", "Failed funding."),
        allocution: "\"I believed it would come together.\"",
        truths: ("{DL} spent $90,000 on a rented villa.", "Investor emails show a real funding attempt."),
        defendant: [.direct("Did you plan to hold the festival?", "\"Yes. I truly planned to hold it. I worked for months on the site, the lineup, and the chefs.\""), .direct("Why did the festival not happen?", "\"The funding I expected fell through, and I could not build the stages. It collapsed close to the date.\""), .direct("Why did you spend $90,000 on a villa?", "\"For meetings with investors and vendors. I used it as a base, and I thought it was part of the budget.\""), .direct("How did you plan the festival?", "\"I booked artists, chefs, and a venue with deposits and put out ads. I thought ticket sales and investor money would cover the build.\""), .direct("What happened to the investors?", "\"Two backed out in the last month, and I did not have the funds to build the stages. I kept hoping for a rescue.\""), .direct("What was the villa?", "\"A rental I used as an office and meeting place for vendors for a couple of months. It cost about $90,000 and I paid it from ticket money.\""), .cross("The stage photos in your posts were not real, were they?", "\"They were mockups of what we planned to build. I should have labeled them clearly.\""), .cross("$410,000 in ticket sales, and no refunds. Where did it go?", "\"Much of it went to expenses and deposits. I did not have enough left to refund everyone.\""), .cross("2,000 people showed up to an empty field. Do you accept that you took their money?", "\"Yes. I truly am sorry. I never meant for it to end that way.\""), .cross("You sold 2,000 tickets and spent ticket money on a villa, didn't you?", "\"Yes, and I see how that looks. I thought of the villa as part of the business.\""), .cross("The stage photos were not of anything built, were they?", "\"No. They were mockups, and I should have labeled them that way.\"")],
        openings: ("{D}, a promoter, sold 2,000 tickets worth $410,000 for a luxury coast festival. On the festival date, guests arrived at an empty field, and the bank records show the money moved to {D}'s own accounts.", "The defense evidence will establish that {D} sought real funding, that investor emails prove it, and that the festival collapsed when the money never came."),
        closings: ("Two thousand tickets, $410,000, photos of stages that never existed, and a villa rented with ticket money. Guests arrived to an empty field.", "A promoter who tried to raise real funding and failed. A business failure is not a crime, and the State must prove {D} never meant to hold the festival."),
        timeline: [(-90, "Ticket sales open."), (0, "Festival day: the field."), (1, "Guests complain."), (14, "Charges.")],
        identified: "Ticket records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I spent my savings on the trip.",
        doctrines: ["burdenOfProof"])

    static let falseTeamAccusation = SmallCases.make(
        key: "story.falseTeamAccusation",
        category: .publicOrder,
        headlines: ["Student Falsely Reported Being Attacked at Team Party", "Photos and Door Camera Disprove Her Account"],
        law: "falseReport",
        threshold: 7,
        spec: "Gave a false report of a crime to a law enforcement officer, on {DATE}.",
        ages: 18...24,
        victim: false,
        summary: "{D} told deputies on {DATE} that three teammates attacked {D.him} at an off-campus party. Doorbell video and photos showed {D} leaving alone and laughing. {DL} says {D.he} was confused after drinking.",
        state: [E(.video, 3, "Doorbell Video", "{D} leaves alone and laughing."), E(.digital, 3, "Photos", "Time-stamped photos of {D} at a diner."), E(.statement, 2, "Deputy", "The story changed twice.")],
        defense: [E(.statement, 1, "Confusion", "{DL} says {D.he} was confused after drinking.")],
        role: "Deputy",
        exam: [.direct("What did {DL} tell you on {DATE}?", "\"That three teammates attacked {D} at an off-campus party. I took a report and began investigating.\""), .direct("What did the doorbell video and photos show?", "\"It shows {DL} leaving alone and laughing. And time-stamped photos of {DL} at a diner after the party.\""), .direct("Did {DL}'s story change?", "\"Twice. Each version differed on details of the attack. That's in my notes.\""), .direct("How did you receive the report?", "\"A call came in at about one in the morning from {D.him}, who said three teammates had jumped {D.him} at a house party. {D.He} sounded upset.\""), .direct("What details did {D} give?", "\"The first time, {D.he} said three teammates held {D.him} down and hit {D.him}. The second time, the number changed and so did who threw punches.\""), .direct("What did you check?", "\"We pulled a neighbor's doorbell video and found time-stamped photos from a diner. They show {DL} leaving the party alone and laughing, then eating a burger at 11:40.\""), .cross("{DL} says {D.he} was confused after drinking, doesn't {D.he}?", "\"Drinking can confuse memory. But {D.he} gave specifics about three attackers.\""), .cross("Did {DL} have any injuries?", "\"I didn't see any. {D.He} didn't have visible marks that I noted.\""), .cross("Did you charge the teammates?", "\"No. After the video I did not. They were cleared.\""), .cross("You saw no marks on the defendant, did you?", "\"No bruises, cuts, or torn clothing. {D.He} smelled strongly of alcohol.\""), .cross("You did not arrest the defendant that night, did you?", "\"No. I told {D.him} to sleep it off and call me back. The video came a day later.\"")],
        defenseRole: "Roommate",
        defenseExam: [.direct("Do you live with {DL}?", "\"Yes. I saw {D} that night when {D.he} got in.\""), .direct("How drunk was {DL}?", "\"Very. {D.He} could barely hold a conversation. {D.He} was slurring.\""), .direct("Did {DL} seem hurt?", "\"No. I didn't see any injuries. {D.He} was loud and confused.\""), .direct("How do you know {D}?", "\"We are roommates in an apartment near campus and have lived together for a full year. We share a kitchen and a living room and see each other daily.\""), .direct("What condition was {D} in when {D} came home that night?", "\"Very drunk, loud, and stumbling. {D.He} flopped on the couch, mumbled about the party, and was asleep within a few minutes of walking in the door.\""), .direct("Did {D} say anything to you about an attack?", "\"Only that the party was bad and the team was out to get {D.him}. Nothing about being hit or held down, and nothing that sounded like an assault.\""), .cross("Was {DL} walking fine?", "\"Fine. {D.He} walked in on {D.his} own. Drunk but steady.\""), .cross("Did {DL} mention an attack?", "\"Not to me. Not then. I only heard about it later.\""), .cross("Was {DL} laughing?", "\"Maybe. I don't remember. {D.He} was in a strange mood.\""), .cross("{D} had no visible injuries when you saw {D.him}, did {D.he}?", "\"None that I could see. {D.his} face, hands, and arms looked fine under the living room light, and {D.he} was not holding any body part.\""), .cross("You were not at the party yourself, were you?", "\"No, I stayed home that night. I only know what I saw when {D.he} came through the door and what the deputies told me afterward.\"")],
        theory: ("{D} lied about an attack.", "A confused drunk."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had been in trouble with the team.", "{DL} blew a .14 that night."),
        defendant: [.direct("Why did you tell deputies you were attacked?", "\"I'd been drinking, and I was confused. I thought something had happened at the party, and I reported it.\""), .direct("What do you remember?", "\"Pieces. I remember an argument, and then I was out. I don't remember an attack, but I believed it.\""), .direct("Did you mean to lie?", "\"No. I didn't mean to hurt anyone. I told what I believed, and it was wrong.\""), .direct("How much had you had to drink?", "\"A lot. I lost count after the sixth. I blew a .14 later that night.\""), .direct("What do you remember about the party?", "\"An argument with some teammates over a team issue, and then I walked out. After that it is fragments.\""), .direct("What were you thinking when you called?", "\"That I had been jumped. My head was full of an argument and I turned it into an attack.\""), .cross("The doorbell video shows you laughing, doesn't it?", "\"Yes. I was drunk. I don't remember laughing.\""), .cross("You told three different stories, didn't you?", "\"Yes. I kept changing it. I was trying to remember.\""), .cross("Three teammates were accused, weren't they?", "\"Yes. I'm so sorry. They didn't do anything.\""), .cross("You had a conflict with the team before, didn't you?", "\"Yes, I had been in trouble with the coach and some players. That is part of why I blamed them.\""), .cross("Your first and second stories were different, weren't they?", "\"They were. I added things as I went, and none of it was true.\"")],
        openings: ("{D} told deputies that three teammates attacked {D} at an off-campus party, but doorbell video shows {D} leaving alone and laughing. Photos put {D} at a diner. The State will present the deputy and the video.", "The defense evidence includes a student who was very drunk, confused about what happened, and who told what {D.he} believed. Listen closely to the witnesses."),
        closings: ("A story told to deputies that changed twice, a video of {D} leaving alone and laughing, and teammates who were nearly charged for something that never happened. A false report costs real people.", "{D} was drunk and confused, and believed what {D.he} reported. The State has not proved {D} knew the story was false, only that alcohol and a team grudge had clouded {D.his} mind."),
        timeline: [(0, "11 p.m.: the party."), (0, "11:40 p.m.: the diner."), (0, "1 a.m.: the report."), (2, "The video surfaces.")],
        identified: "Video and photos.",
        mood: .divided,
        impact: "Our names were in the paper for weeks.",
        doctrines: ["intoxication"],
        genders: ["D": .female])

    static let deviceOnDeliveryDriver = SmallCases.make(
        key: "story.deviceOnDeliveryDriver",
        category: .violent,
        headlines: ["Delivery Driver Forced Into Bank Robbery With Fake Device Strapped On", "Plotter's Phone Gave Instructions"],
        law: "kidnapping2",
        threshold: 8,
        spec: "Unlawfully confined, restrained and removed {V} by force or threat, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a delivery driver, was lured to a remote address on {DATE} and fitted with a device told to be a bomb. {V.he} robbed a bank under instructions. The device was fake. {D}, a customer who ordered, was traced. {DL} says {D.he} only ordered food.",
        state: [E(.digital, 3, "Call Records", "Calls to {V}'s phone from a burner."), E(.physical, 3, "Fake Device", "Parts bought by {D}.", .search), E(.video, 2, "Bank Camera", "{V} reads a note.")],
        defense: [E(.statement, 1, "Order", "{DL} says {D.he} only ordered food.")],
        role: "Detective",
        exam: [.direct("What did you learn about the delivery driver's ordeal?", "\"{V} was lured to a remote address on {DATE} and fitted with a device {V} was told was a bomb. Under instructions, {V} robbed a bank.\""), .direct("What was the device?", "\"Fake. Parts for it were bought by {D}, and we recovered them. The device couldn't have exploded.\""), .direct("How was {DL} traced?", "\"Calls came to {V}'s phone from a burner. {DL} had placed the order that lured {V}, and the parts led us to {DL}.\""), .direct("How did the incident start for {V}?", "\"{V} picked up an order for a remote address at about 6 p.m. and was met at the door by someone who strapped a device around {V}'s neck.\""), .direct("What was {V} told to do?", "\"By phone, {V} was told the device was a bomb and to rob a bank or it would be detonated. {V} walked into the bank with a note.\""), .direct("How did you trace the order?", "\"The food order came from an account linked to {D.him}, and the address was near {D.his} home. We traced calls to {V}'s phone to a burner.\""), .cross("{DL} says {D.he} only ordered food, doesn't {D.he}?", "\"The order was real. But the order brought {V} to the address.\""), .cross("Was the burner found with {DL}?", "\"No. I did not recover the burner from {D.him}. I can't say who held it.\""), .cross("Did {V} see who fitted the device?", "\"{V} saw a person but could not identify anyone. {V} was terrified.\""), .cross("You never found the burner phone with {D}, did you?", "\"No, we did not recover it. The calls were traced only to a number.\""), .cross("The device parts could have been bought by anyone, couldn't they?", "\"Yes. They are common items. {D.his} receipts matched the type and quantity.\"")],
        defenseRole: "Hardware clerk",
        defenseExam: [.direct("What did {DL} buy at your store?", "\"Wire and tape. {D} came in and bought them like many customers.\""), .direct("Was it unusual?", "\"No. We sell it all the time. Nothing about it stood out.\""), .direct("How did {DL} act?", "\"Friendly and normal. Asked where the tape was and paid.\""), .direct("What do you do at the store?", "\"I work the register and help customers find supplies. I have worked in that hardware store for four years and know most of the regulars.\""), .direct("What do you recall about {D}'s purchase?", "\"A few spools of wire, a roll of electrical tape, and some small connectors. It looked like a typical home repair purchase to me.\""), .direct("What did the defendant say while you rang it up?", "\"Something about fixing a lamp that had gone out. We chatted for a minute about the weather and the sale on light bulbs.\""), .cross("Did {DL} buy often?", "\"Once. I recall only one purchase.\""), .cross("What else did {DL} buy?", "\"Only wire and tape. I don't recall anything else.\""), .cross("Could you tell what it was for?", "\"No. I never ask. Customers buy supplies for all sorts of things.\""), .cross("You cannot say what the defendant did with those items afterward, can you?", "\"No. Once a customer carries items out the door I have no idea what happens to them, and I never saw {DF} again.\""), .cross("The receipts match what the defendant bought, don't they?", "\"Yes, that is what the paper shows. I have no reason to doubt it, since the register records every item sold.\"")],
        theory: ("{D} used a driver as a courier.", "Only an order."),
        allocution: "\"I never meant anyone harm.\"",
        truths: ("{DL}'s receipts matched the device parts.", "The burner phone was never found with {DL}."),
        defendant: [.direct("Did you order the food?", "\"Yes. I ordered a meal. That's all I did. I didn't know {V} would be harmed.\""), .direct("Did you build the device?", "\"No. I never built anything. I bought some wire and tape for a project.\""), .direct("What project?", "\"Home repairs. I buy wire and tape like anyone. I didn't know someone would use something like it.\""), .direct("Why did you order from that address?", "\"It was my home. I order delivery often and it was a normal evening.\""), .direct("What did you do after you placed the order?", "\"I watched television and waited. I did not see the driver or know anything was wrong.\""), .direct("What did you buy at the hardware store?", "\"Wire, tape, and a few small parts for a repair at home. I paid with my card.\""), .cross("The parts in the device match what you bought, don't they?", "\"Wire and tape are common. I can't explain a match.\""), .cross("The order that lured {V} came from you, didn't it?", "\"Yes. I placed it. I did not know it would be used.\""), .cross("You live near the address, don't you?", "\"Yes. That's why I ordered there. It's my home area.\""), .cross("The device used wire and tape, didn't it?", "\"Yes, among other things, but those are everywhere. It is not my idea.\""), .cross("You live very near the address where the driver was met, don't you?", "\"Yes, a few blocks away. It does not mean I was involved.\"")],
        openings: ("{V}, a delivery driver, was lured to a remote address and fitted with a device said to be a bomb, then forced to rob a bank. The device was fake, built from parts bought by {D}, a customer who placed the order. The State will present the detective.", "The defense will point you to a customer who only ordered food, bought ordinary wire and tape once, and whose burner phone was never found. Listen closely to the witnesses."),
        closings: ("A lured delivery driver, a fake bomb, a forced bank robbery, and parts bought by {D}, who placed the order. The pieces connect.", "Wire and tape are everywhere, and no burner phone was ever found with {D}. The State has not proved {D} built the device."),
        timeline: [(0, "6 p.m.: the order."), (0, "6:30 p.m.: the device."), (0, "7 p.m.: the bank."), (1, "{DL} is traced.")],
        identified: "Call records and parts.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I still think about the countdown.",
        doctrines: ["burdenOfProof"])

    static let lotteryClerkInsider = SmallCases.make(
        key: "story.lotteryClerkInsider",
