        mood: .wantsConviction,
        impact: "I still can't bend without pain.",
        doctrines: ["expertTestimony"])

    static let phantomPatientClaims = SmallCases.make(
        key: "story.phantomPatientClaims",
        category: .whiteCollar,
        headlines: ["Billing Company Sent Claims for Patients Who Never Existed", "Social Security Numbers Reused"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "Presented false claims to an insurer, {V}, totaling $480,000, on or about {DATE}.",
        ages: 28...65,
        victim: true,
        summary: "{D}'s billing company submitted $480,000 in claims on {DATE} for 140 patients who did not exist. Numbers were reused. {DL} says a software bug generated records.",
        state: [E(.document, 3, "Claim Files", "140 patients that do not exist."), E(.digital, 3, "Server Logs", "Records created from {D}'s login."), E(.document, 2, "Payments", "Insurer paid $480,000.")],
        defense: [E(.statement, 1, "Bug", "{DL} says a software bug generated records.")],
        role: "Insurance investigator",
        exam: [.direct("What did you find in the claim files?", "\"Claims for 140 patients who do not exist. Patient numbers were reused across records.\""), .direct("What do the server logs show?", "\"Records created from {D}'s login. The logs tie the creation of those patients to {D.his} account.\""), .direct("How much did the insurer pay?", "\"$480,000. The payment records show the money going out to {D.his} billing company.\""), .direct("How did the claims get flagged?", "\"Our system flagged a billing company for unusual growth in patients with sequential identifiers and similar addresses. I opened a file and requested records.\""), .direct("What did you find when you called patients?", "\"None of the 140 could be reached. Phone numbers were disconnected or belonged to unrelated people, and no medical provider had ever seen them.\""), .direct("What did the server logs reveal?", "\"Records created at all hours from a login assigned to {D.him}. Many were created in bulk in a few minutes.\""), .cross("{D} says a software bug generated records, doesn't {D.he}?", "\"Yes. A vendor logged a duplicate-record bug. That is accurate.\""), .cross("Could a bug create 140 patients?", "\"I doubt it. The bug logged was about duplicates, not new people.\""), .cross("Was the login shared?", "\"I understand {D.his} login may have been shared. That is something we looked at.\""), .cross("A bug can duplicate records, can't it?", "\"Yes, the vendor logged a duplicate-record bug. It would copy an existing record, not invent a new person.\""), .cross("The login was shared among staff, wasn't it?", "\"I was told so. The logs show the same credentials from several addresses.\"")],
        defenseRole: "Software vendor",
        defenseExam: [.direct("Was there a bug in your billing software?", "\"Yes, one. It was a duplicate-record bug that created repeat entries in some situations when records were saved.\""), .direct("Could that bug create 140 brand-new patients?", "\"No, it could not. It could duplicate an existing record, but it could not invent a new patient from nothing.\""), .direct("Did {D} report the bug to you?", "\"Yes. {D} reported a problem, and we logged it as a ticket. I remember handling that ticket.\""), .direct("What is your role with the software?", "\"I work for the vendor in support and fixes. {D.He} reported a problem and we investigated.\""), .direct("What was the bug?", "\"A routine that sometimes duplicated an existing patient record when two offices submitted similar data. It was fixed in a later update.\""), .direct("Does the system create patients with new names?", "\"No. It cannot invent a patient. It only copies or merges existing data.\""), .cross("Would a duplicate bug explain reused patient numbers?", "\"Possibly for some of them. But 140 distinct patients is far more than duplication would produce.\""), .cross("Did anyone else have access to the defendant's login at the company?", "\"I do not know for certain. It is possible, but I cannot say who might have used it.\""), .cross("Does your software ever submit claims on its own?", "\"No. A person has to submit each claim, and nothing in the system sends claims automatically.\""), .cross("The bug could not explain 140 distinct people, could it?", "\"No. I would not expect that from this bug.\""), .cross("Someone would have to type or import new patient data, wouldn't they?", "\"Yes. Someone with access to the entry screens.\"")],
        theory: ("{D} billed for ghost patients.", "A software bug."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} bought a vacation property.", "A vendor logged a duplicate-record bug."),
        defendant: [.direct("Did you create those 140 patients?", "\"No, I did not create them. A software bug generated records, and I did not catch it in time.\""), .direct("Was there really a bug in the software?", "\"Yes. The vendor logged one. I reported it myself, and I believe it caused some of what happened.\""), .direct("What about the vacation property you bought?", "\"I bought it with savings that I had built up. It had no connection to the insurance claims.\""), .direct("How does your company bill?", "\"We submit electronic claims on behalf of medical offices. Our software generates records from data the offices send.\""), .direct("What did you notice about the software?", "\"Duplicate patient entries appeared in reports, and I reported it to the vendor. They logged a bug.\""), .direct("What did you do with the money?", "\"It went to the company account for payroll and expenses. I also bought a vacation property earlier that year with savings.\""), .cross("The records came from your login, didn't they?", "\"My login was shared among the staff at the company. Others used it too, and I did not control that.\""), .cross("140 phantom patients and $480,000 paid out. Where did the money go?", "\"To the company. I did not put it in my own pocket, and the books will show where it went.\""), .cross("You never noticed that patients did not exist?", "\"I did not review each record. I should have, and I am sorry that I did not.\""), .cross("You never reviewed patient names against any real list, did you?", "\"No. I trusted the system, and I should have audited it.\""), .cross("Your login created records at night, didn't it?", "\"So the logs say. I did not do that.\"")],
        openings: ("{D}'s billing company submitted $480,000 in claims for 140 patients who do not exist, with reused numbers and records created from {D}'s login. {D} later bought a vacation property.", "The defense evidence will establish that a vendor logged a duplicate-record bug, that the login was shared, and that the property was bought with savings."),
        closings: ("A hundred forty patients who do not exist, $480,000 paid, records from {D}'s login, and a vacation home. Software does not invent patients.", "A logged software bug, a shared login, and a company that submitted claims it believed were real. The State must prove {D} knew they were false."),
        timeline: [(-300, "Claims begin."), (0, "Year 1: audit."), (0, "Year 1: logs."), (30, "Charges.")],
        identified: "Server logs.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let tornadoReliefKept = SmallCases.make(
        key: "story.tornadoReliefKept",
        category: .whiteCollar,
        headlines: ["Charity Collected for Tornado Victims and Kept Most of It", "$140,000 Raised, $9,000 Delivered"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and other donors, on or about {DATE}.",
        ages: 30...65,
        victim: true,
        summary: "After a tornado, {D}'s charity raised $140,000 on {DATE} and delivered $9,000 to victims. The rest paid {D}'s salary and a truck. {DL} says overhead costs were high.",
        state: [E(.document, 3, "Charity Ledger", "$9,000 delivered; $131,000 spent elsewhere."), E(.document, 3, "Donor Pitch", "'Every dollar goes to families.'"), E(.statement, 2, "Shelter", "Few deliveries.")],
        defense: [E(.statement, 1, "Overhead", "{DL} says overhead costs were high.")],
        role: "Donor",
        exam: [.direct("What did you give to {D}'s charity?", "\"A donation after the tornado, based on a pitch that said, 'Every dollar goes to families.'\""), .direct("What did the ledger show?", "\"Only $9,000 delivered to victims out of $140,000 raised. The other $131,000 was spent elsewhere.\""), .direct("What did the shelter say?", "\"Few deliveries had arrived. The shelter reported getting very little.\""), .direct("What did you see in the pitch?", "\"A flyer and a web page with pictures of damaged homes and the line, every dollar goes to families. I gave $500 online that night.\""), .direct("What did you learn later?", "\"A reporter asked where the money went, and I looked up the charity's filing. It showed $9,000 delivered out of $140,000 raised.\""), .direct("What did the shelter tell you?", "\"They said few supplies had come, and they were still short of water and tarps. I felt betrayed.\""), .cross("{D} says overhead costs were high, doesn't {D.he}?", "\"Yes. But a $70,000 salary and a truck are a lot of overhead for a new charity.\""), .cross("Were some deliveries made by volunteers?", "\"I understand volunteers delivered loads that were not logged. That may be true.\""), .cross("Was the truck used for charity?", "\"I believe it was, at least in part. I cannot say how much.\""), .cross("A new charity has startup costs, doesn't it?", "\"Yes, and I do not object to reasonable costs. A $70,000 salary on top of a truck is more than that.\""), .cross("You did not read the fine print about fees before donating, did you?", "\"No. I trusted the headline on the page.\"")],
        defenseRole: "Volunteer driver",
        defenseExam: [.direct("Did you deliver supplies for the charity?", "\"Yes, many loads. I drove food, water, and tarps to families after the tornado.\""), .direct("Were those deliveries logged?", "\"No. We did not keep logs. We were busy, and we just loaded and went.\""), .direct("How many loads did you carry?", "\"Many. Dozens, I would say, over several weeks. I stopped counting.\""), .direct("How did you help?", "\"I drove my own pickup to the charity's warehouse, loaded food and tarps, and took them to shelters. I did it for about six weeks.\""), .direct("Did you ever see {D} working?", "\"Yes, {D} was at the warehouse nearly every day, loading boxes and answering phones.\""), .direct("What did you do when you heard about the money?", "\"I told people what I had delivered. I never saw a ledger.\""), .cross("Did you receive any pay from the charity?", "\"No. I volunteered. I did not take anything for my work.\""), .cross("Did the defendant know about your deliveries?", "\"Yes. {D.He} knew, and {D.he} thanked us. But I do not know how {D.he} tracked it.\""), .cross("Can you prove the deliveries happened?", "\"Only by my word and others. We kept no logs.\""), .cross("You did not keep a log of your deliveries, did you?", "\"No. We all just drove.\""), .cross("You do not know how the money was spent, do you?", "\"No. I never saw a statement.\"")],
        theory: ("{D} kept donations.", "High overhead."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} paid a $70,000 salary.", "Some deliveries were by volunteer drivers unlogged."),
        defendant: [.direct("Did you keep the donations?", "\"No. Most of it went into the work. I paid a salary and bought a truck to run the charity.\""), .direct("How much was your salary?", "\"$70,000. I thought that was fair for the work I did full time.\""), .direct("What about the logs of deliveries?", "\"They are missing. Volunteers made many deliveries and we did not log them.\""), .direct("How did you start the charity?", "\"I formed it after the tornado with a few volunteers and a loan from a friend. Donations came in faster than I expected.\""), .direct("How was the money used?", "\"About $70,000 for my salary, a truck for deliveries, insurance, and ads. The rest went to supplies and volunteer gas money.\""), .direct("Why were deliveries not logged?", "\"We were moving loads out of a warehouse every day, and I did not stop to write them down. Most of it was carried by volunteers.\""), .cross("'Every dollar goes to families.' Is that true when you took a $70,000 salary?", "\"It was a figure of speech. I did not mean to mislead anyone.\""), .cross("$9,000 delivered out of $140,000. Doesn't that seem small?", "\"It is small on paper. Many deliveries were not logged.\""), .cross("You bought a truck with donations, didn't you?", "\"It was a charity truck. I used it for deliveries.\""), .cross("The pitch said every dollar goes to families, didn't it?", "\"Yes, and I should not have used that line. It was not literally true.\""), .cross("You paid yourself a salary out of donations, didn't you?", "\"I did, and I thought it was fair for full-time work.\"")],
        openings: ("After a tornado, {D}'s charity raised $140,000 with the pitch 'Every dollar goes to families.' The ledger shows only $9,000 delivered to victims, and the rest paid {D}'s salary and a truck.", "By the end of this trial, the proof will show that volunteers made many deliveries that were never logged and that a charity must pay real costs to operate at all."),
        closings: ("$140,000 raised, $9,000 delivered, a $70,000 salary, and a promise that every dollar goes to families. That promise was false, and donors relied on it.", "A new charity with high costs and volunteers who did not log their loads. The State must prove {D} intended to deceive donors, and poor records are not fraud."),
        timeline: [(-30, "The tornado."), (0, "The drive."), (60, "Donors ask."), (120, "Charges.")],
        identified: "Charity ledger.",
        aggravating: ["The offense was committed for pecuniary gain", "The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "We were living in a tent.",
        doctrines: ["burdenOfProof"])

    static let slowCarHoodClaims = SmallCases.make(
        key: "story.slowCarHoodClaims",
        category: .whiteCollar,
        headlines: ["Man Threw Himself Onto Slow-Moving Cars to Collect Injury Claims", "Same Man, Nine Accidents"],
