        defense: [E(.statement, 1, "Bad Luck", "{DL} says it was bad luck.")],
        role: "Insurance investigator",
        exam: [.direct("What did you find when you reviewed {D}'s claims?", "\"Nine claims in two years for being struck at low speed by cars. The same clinic treated {D} each time.\""), .direct("What do the dash camera clips show?", "\"It shows {DL} stepping in front of slow-moving cars. It happens in several of the clips.\""), .direct("What pattern did you see?", "\"Low-speed contacts, minor injuries, and the same clinic. That is a common pattern for staged claims.\""), .direct("How did you notice the pattern?", "\"An analyst saw nine claims in two years from one person for being struck while walking, all with similar injuries and the same clinic.\""), .direct("What did you do?", "\"I asked drivers' insurers for dash camera footage. In several clips, {D.he} steps off the curb as slow traffic rolls and ends up at the bumper.\""), .direct("What did the clips show?", "\"Cars at five to ten miles per hour with {DL} stepping in front, often looking at the car first. After contact, {DL} grabs a hip or arm.\""), .cross("{D} says it was bad luck, doesn't {D.he}?", "\"Yes. {D.He} walks to work near busy streets, so exposure could explain some of it.\""), .cross("Were some injuries real?", "\"Yes. Some were documented as real. That is accurate.\""), .cross("Is the clinic the closest to {D}'s home?", "\"I understand it is. That would explain going there each time.\""), .cross("Pedestrians often cross in front of slow cars, don't they?", "\"Yes. That is normal behavior. The repetition is what stood out.\""), .cross("Some injuries were documented as real, weren't they?", "\"Yes. A few had bruising confirmed by the clinic.\"")],
        defenseRole: "Nurse",
        defenseExam: [.direct("Were {D}'s injuries real when you treated {D.him}?", "\"Bruises, yes. I saw them myself at the clinic. They were consistent with a minor impact from a slow car.\""), .direct("Were those injuries serious?", "\"Minor. Nothing that needed hospitalization. Just bruising and soreness, which usually clears up in a few weeks.\""), .direct("Did the defendant seem to be exaggerating the pain?", "\"No. {D} reported what hurt, and I recorded it carefully. I did not sense any exaggeration.\""), .direct("What is your role at the clinic?", "\"I am a nurse who sees walk-ins for minor injuries. I treated {D.him} on several visits.\""), .direct("What did you find?", "\"Mild bruising and soreness at the hip and forearm. The injuries matched the story.\""), .direct("How did the defendant act?", "\"Calm and straightforward. {D.He} never asked for pain medicine or time off.\""), .cross("Did you treat the defendant nine times at your clinic?", "\"Several times, yes. I do not remember the exact count, but it was more than a few.\""), .cross("Did the defendant say each time that a car had bumped {D.him}?", "\"Yes. {D.He} said cars had bumped into {D.him} each time, and I recorded the history as given.\""), .cross("Does it seem unusual to you to be struck so often?", "\"Yes, it is unusual. But I treated what I saw, and I do not decide how an injury happened.\""), .cross("You cannot say how the injuries happened, can you?", "\"No. I only recorded what {D.he} reported and what I saw.\""), .cross("The same person arriving repeatedly would catch your eye, wouldn't it?", "\"Yes, and I mentioned it to the doctor once.\"")],
        theory: ("{D} staged accidents.", "Bad luck."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} walked to work near busy streets.", "Some injuries were documented as real."),
        defendant: [.direct("Did you stage these accidents?", "\"No. I did not. I walk to work near busy streets, and I was hit by slow cars.\""), .direct("Why the same clinic each time?", "\"It is the closest clinic to my home and work. I went where it was convenient.\""), .direct("Were your injuries real?", "\"Some were. I had bruises and soreness after being hit.\""), .direct("How do you get to work?", "\"I walk about two miles through busy streets, since I do not have a car. I cross at the same intersections each day.\""), .direct("What happened in those incidents?", "\"Cars rolled into me while I crossed, sometimes because I thought the driver would stop. I felt a bump and some pain.\""), .direct("Why file claims?", "\"Because I was sore and had medical visits to pay. I thought that was what insurance was for.\""), .cross("Nine times in two years. Isn't that hard to believe?", "\"It is a lot. I know. It is bad luck and a busy route.\""), .cross("The dash cameras show you stepping in front of cars. Why?", "\"I was crossing. I did not step in front on purpose.\""), .cross("You filed nine claims. How much did you collect?", "\"A modest amount. I did not keep track.\""), .cross("Nine incidents in two years is rare, isn't it?", "\"It is, and I know it looks odd. I cross many streets a day.\""), .cross("You looked at the drivers before stepping out, didn't you?", "\"Sometimes, to make eye contact. I did not expect them to roll forward.\"")],
        openings: ("{D} was struck at low speed by nine cars in two years and filed nine injury claims, always at the same clinic. Dash cameras show {D} stepping in front of slow-moving traffic.", "The defense will present evidence that {D} walks to work near busy streets, that some injuries were documented as real, and that the clinic was simply the closest."),
        closings: ("Nine slow-speed contacts, nine claims, one clinic, and dash cameras showing {D} stepping into traffic. Bad luck does not repeat like that.", "A pedestrian near busy streets, real bruises, and the closest clinic. The State must prove {D} staged the crashes, and bad luck is not fraud."),
        timeline: [(-700, "The first claim."), (0, "Year 2: the ninth claim."), (0, "Year 2: the clips."), (90, "Charges.")],
        identified: "Dash camera clips.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let localCelebrityTracker = SmallCases.make(
