        defense: [E(.statement, 1, "Neighbor Request", "{DL} says a neighbor asked.")],
        role: "Deputy",
        exam: [.direct("What did the trail camera show after the hurricane?", "\"It shows {D} carrying a generator out of {V}'s flooded home at night. The street was closed by an evacuation notice.\""), .direct("How was the street restricted?", "\"An evacuation notice closed it. A truck was seen on the closed street at about 2 a.m., and {V} returned the next day.\""), .direct("What did you find when you searched {D}'s vehicle five days later?", "\"Tools with {V}'s engraving on them. The search also confirmed {DL} had loaded a truck at night.\""), .direct("What was the situation on the street after the storm?", "\"A hurricane had flooded the whole neighborhood, and the county closed the street with a notice at both ends. Residents had been told to stay out until the water receded.\""), .direct("How did your deputies come across this?", "\"A neighbor reported a truck on the closed street at about two in the morning. We pulled up trail camera footage that showed {DL} carrying a generator out of {V}'s house.\""), .direct("What did you find in the defendant's truck?", "\"A generator, a tool chest, and several power tools. Some of them had {V}'s name engraved on the handles.\""), .cross("{D} says a neighbor asked {D.him} to save belongings, doesn't {D.he}?", "\"Yes. {DL} says that. The neighbor told us there was no request, but I will repeat what {DL} says.\""), .cross("Could someone take belongings from a flooded home to save them?", "\"In an emergency, a neighbor might. But a truck at 2 a.m. and a generator are unusual ways to do it.\""), .cross("Did the defendant try to hide what was in the truck?", "\"No. {D.He} was open when we searched. {D.He} said the tools were borrowed.\""), .cross("A neighbor can legitimately ask someone to save belongings, can't they?", "\"They can, and that is why we spoke to the neighbor. The neighbor said no such request was made.\""), .cross("The home was flooded when the defendant entered, wasn't it?", "\"Yes, water was a foot deep in the garage. Items there could have been damaged if left.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Did {D} ask you whether to save {V}'s belongings?", "\"No. {D} did not ask me anything about that. I was not part of any request.\""), .direct("Did anyone tell the defendant to go into {V}'s home?", "\"I do not know who would have. I did not, and I did not hear of anyone else doing it.\""), .direct("Where were you the night of the storm?", "\"At a shelter with my family. I did not come back until the next day, when the water went down.\""), .direct("How do you know the defendant?", "\"We live a few blocks apart and see each other on walks. I know {D.he} well enough to wave.\""), .direct("Did you speak to the defendant during the storm?", "\"No. I did not talk to {D.him}, and I did not ask {D.him} to do anything.\""), .direct("What did you see on the street the day after the storm?", "\"Debris everywhere, a few trucks, and people going in and out of damaged houses. I did not see anyone loading things from {V}'s house that I could name.\""), .cross("Did you ever tell the defendant to save belongings from any home?", "\"No. I never told {D.him} to do that at any home, including mine.\""), .cross("Were there other people going into homes that night?", "\"I heard there might have been. I did not see anyone myself.\""), .cross("Do you know {D} well?", "\"We are neighbors. I know {D.him} to wave to, and I know that {D.he} has tools.\""), .cross("You never asked the defendant to rescue anything from {V}'s home, did you?", "\"No, I did not, and I told the deputies the same thing.\""), .cross("You do not know what the defendant did that night, do you?", "\"No. I only know what the deputies told me later.\"")],
        theory: ("{D} stole from a flooded home.", "Rescuing property."),
        allocution: "\"I took what I shouldn't have.\"",
        truths: ("{DL} loaded a truck at night.", "The neighbor says no request."),
        defendant: [.direct("Why did you enter {V}'s flooded home?", "\"To save things. The water was rising, and I thought I could get some belongings out before they were ruined.\""), .direct("Why did you take the generator?", "\"It was in the garage, and I thought it was in danger of being ruined by the water. I planned to give it back.\""), .direct("Why did you go at night?", "\"It felt safer. The street was closed, and I did not want to get stopped or be in anyone's way.\""), .direct("How did you hear about the home?", "\"A neighbor told me the family was out of town and the water was rising in the garage. They said it was a shame to lose everything.\""), .direct("What did you do?", "\"I took my truck down the closed street late that night and moved what I could from the garage and workbench. I thought I was keeping it from ruin.\""), .direct("Why did you keep the tools?", "\"I put them in my truck bed and planned to return them in a few days when the water went down. I never had the chance.\""), .cross("The street was closed under an evacuation notice, wasn't it?", "\"Yes. I knew it was closed. I went in anyway because I thought I was helping.\""), .cross("Tools with {V}'s engraving were in your truck. Why?", "\"I borrowed some tools from the house to use for cleanup, and I meant to bring them back.\""), .cross("A neighbor says no one asked you. Who did?", "\"I was told by someone. I cannot name the person now, and I know that sounds convenient.\""), .cross("You went at two in the morning on a closed street, didn't you?", "\"Yes. I knew it was closed, and I told myself the emergency allowed it.\""), .cross("You cannot name the neighbor who asked you, can you?", "\"Not at the moment. It was a brief conversation, and I did not get a name.\"")],
        openings: ("After a hurricane, {D} entered {V}'s flooded home on a closed street at night and carried out tools and a generator. A trail camera shows it, and a search found tools with {V}'s engraving in {D}'s truck.", "The defense witnesses will explain that {D} entered to save belongings from rising water and meant to return what was taken, with no plan to steal."),
        closings: ("A closed street, a night-time truck, a generator on camera, and tools with {V}'s engraving in {D}'s own vehicle. A person saving belongings does not need to carry them home in secret.", "A flood, an emergency, and a neighbor who tried to help and used poor judgment. The State must prove {D} meant to keep what was taken, and an honest rescue is not a burglary."),
        timeline: [(-1, "Storm."), (0, "2 a.m.: truck on the street."), (1, "Owner returns."), (5, "Search.")],
        identified: "Trail camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let vacationRentalNoHouse = SmallCases.make(
        key: "story.vacationRentalNoHouse",
        category: .whiteCollar,
        headlines: ["Host Rented a Beach House He Did Not Own to 40 Families", "Families Arrive to a Locked Door and a Stranger"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained money from others by false pretenses, on or about {DATE}.",
        ages: 22...65,
        victim: false,
        summary: "{D} listed a coast house on a rental site on {DATE} and collected deposits of $38,000 from 40 families. The home belongs to someone else. {DL} says {D.he} was a manager with a lapsed lease.",
        state: [E(.digital, 3, "Listing", "Photos taken from another site."), E(.document, 3, "Deed", "Owner is a third party."), E(.digital, 2, "Payment Records", "$38,000 to {D}.")],
        defense: [E(.document, 1, "Lapsed Lease", "{DL} once managed the home.")],
        role: "Guest",
        exam: [.direct("What did you book through the rental site?", "\"A coast house for my family, based on a listing with beautiful photos. I paid a deposit to {D}.\""), .direct("What did you learn about the house?", "\"The house belongs to someone else. The deed shows a third-party owner, and {DL} had no right to rent it.\""), .direct("What about the photos?", "\"They were taken from another site. The listing used pictures that did not belong to that house.\""), .direct("How did you find the listing?", "\"On a vacation rental site, with photos of a three-bedroom house a block from the beach and a calendar showing summer openings. I booked a week in July.\""), .direct("What did you pay?", "\"A $950 deposit through the site's payment link, with the rest due on arrival. I got a confirmation email with directions.\""), .direct("What happened when you arrived?", "\"The key code did not work and a neighbor told us the house had been sold two months earlier. The owner showed up and said it was not for rent.\""), .cross("{D} says {D.he} was a manager with a lapsed lease, doesn't {D.he}?", "\"Yes. {D.He} said that. A booking agent says the lease ended four months before.\""), .cross("Did the defendant refund any guests?", "\"Yes. A few were refunded, I understand. Not all of us were.\""), .cross("How many families paid deposits?", "\"Forty families paid, for $38,000 in all. I was one of them.\""), .cross("You never spoke to the real owner before booking, did you?", "\"No. All communication was with {D.him} through the site.\""), .cross("{D} did refund some families, didn't {D.he}?", "\"I heard that a few were refunded. We were not among them for weeks.\"")],
        defenseRole: "Booking agent",
        defenseExam: [.direct("When did {D}'s lease on the house end?", "\"Four months before the listing I saw. The lease ended and was not renewed, according to the agent's records.\""), .direct("Was the house relisted by the owner?", "\"No. It was not relisted. The owner was not renting it out during that time.\""), .direct("Did the defendant still act as manager?", "\"{D} kept acting like a manager. I do not know why, and I did not approve it.\""), .direct("What is your role?", "\"I work as a booking agent for the rental site, handling listings and payments. I looked at this file after complaints came in.\""), .direct("What did you learn about the house?", "\"That {DF}'s lease ended four months before the guests arrived and the owner had not renewed it.\""), .direct("What did the defendant do on the site?", "\"Kept the listing active and accepted bookings. We did not catch the lapse until complaints.\""), .cross("Did you tell the defendant to stop taking deposits?", "\"I did not know until later. If I had, I would have called {DF} right away.\""), .cross("Was the defendant authorized to book guests after the lease ended?", "\"No. {DF} had no authority to book anyone after the lease ended.\""), .cross("Did {D} keep the owner's keys?", "\"I do not know. I did not ask.\""), .cross("The site checks listings for ownership, don't you?", "\"We check at signup, not every month. That is a gap.\""), .cross("{D} had no right to book anyone, did {D.he}?", "\"None. The lease had ended and the owner never agreed to continue.\"")],
        theory: ("{D} rented a house {D.he} did not control.", "A lapsed lease."),
        allocution: "\"I should have shut it down.\"",
        truths: ("{DL} kept collecting after the lease ended.", "{DL} refunded a few guests."),
        defendant: [.direct("Did you own the coast house?", "\"No. I never owned it. I managed it for the owner under a lease that later lapsed.\""), .direct("Why did you keep taking deposits after the lease ended?", "\"I thought I could renew it. I was in talks with the owner, and I kept bookings going.\""), .direct("Where did the photos come from?", "\"They were old photos from earlier listings. I used what I had, and I did not think it mattered.\""), .direct("How did you come to list that house?", "\"I managed it for the owner under a lease for three years. When the lease ended, I thought the owner would renew.\""), .direct("Why did you keep the listing up?", "\"The summer bookings were already flowing, and I did not want to lose them. I planned to sort it out when the new lease was signed.\""), .direct("What happened to the deposits?", "\"I used some for repairs and expenses on the owner's other properties and refunded a few guests. I did not have enough to cover everyone.\""), .cross("You took deposits from 40 families for a house you could not rent, didn't you?", "\"Yes. I know it looks like fraud. I meant to fix it.\""), .cross("You refunded only a few guests, didn't you?", "\"Some. I did not have the money for all. I am working to repay.\""), .cross("The lease ended four months before. Why still list the house?", "\"I hoped it would be renewed. I should have stopped.\""), .cross("The lease had ended four months earlier, hadn't it?", "\"Yes, and I should have taken down the listing right then.\""), .cross("You took deposits from forty families, didn't you?", "\"Yes, $38,000 in all. I did not stop to count.\"")],
        openings: ("{D} listed a coast house on a rental site and collected $38,000 in deposits from 40 families. The house belongs to someone else, the listing's photos came from another site, and {D}'s lease had ended four months earlier.", "Listen for the defense evidence, which will show that {D} once managed the house, hoped to renew the lease, and refunded some guests when things fell apart."),
        closings: ("Forty families, $38,000, photos from another site, a house owned by a stranger, and a lease that had ended. {D} kept collecting money for a house {D} could not rent.", "A former manager who hoped to renew a lease and refunded several guests. The State must prove {D} never meant to deliver, and a lapsed lease is not a plan to defraud."),
        timeline: [(-120, "The lease ends."), (-60, "Listing stays up."), (0, "Guests arrive."), (10, "Charges.")],
        identified: "Payment records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fairgroundSwingFall = SmallCases.make(
        key: "story.fairgroundSwingFall",
        category: .violent,
        headlines: ["Ride Seat Broke Free at a County Fair, Hurting Six Riders", "Inspection Sticker Signed Without a Look"],
        law: "aisi",
        threshold: 7,
        spec: "Inflicted serious injury on {V} through culpable negligence, on or about {DATE}.",
        ages: 21...65,
        victim: true,
        summary: "A swing ride at a county fair on {DATE} threw six riders when a weld failed. {D}, the operator, signed the inspection sticker. {DL} says a supplier had certified the weld.",
        state: [E(.forensic, 3, "Weld Failure", "A cracked weld with rust."), E(.document, 3, "Inspection Sticker", "Signed by {D}."), E(.document, 2, "Maintenance Log", "No checks for a year.")],
        defense: [E(.document, 1, "Supplier Certificate", "{DL} was told the weld was new.")],
        role: "State inspector",
        exam: [.direct("What happened at the county fair swing ride on {DATE}?", "\"A weld failed and the ride threw six riders. It was a terrible accident.\""), .direct("What did you find in the weld?", "\"A cracked weld with rust. It had been weakening for a while, and rust shows it wasn't new.\""), .direct("What is the role of an inspector at the fair?", "\"I check each ride's structural parts, paperwork, and operator procedures before opening. I also respond when an incident is reported.\""), .direct("What did you find after the failure?", "\"A cracked weld on a support arm with rust along the crack. It had been weakening for some time and finally gave way under load.\""), .direct("What did the paperwork show?", "\"The maintenance log had no weekly checks for a full year. The inspection sticker was signed by {D}.\""), .direct("How often should an operator inspect a swing ride like that?", "\"Moving parts get checked before each opening, and welds and bolts are logged weekly. The log for this ride shows no weekly checks for a year.\""), .cross("{DL} says a supplier certified the weld, doesn't {D.he}?", "\"A certificate exists, saying the weld was new. I can't say how long ago.\""), .cross("Could a weld be new and still fail?", "\"It could, if poorly done. But rust suggests a weld that had been there a while.\""), .cross("Is the operator the one who welds?", "\"No. The operator oversees the ride. A supplier or mechanic does the welding.\""), .cross("A new weld can fail if it is badly done, can't it?", "\"Yes. But a rusted crack is not a new weld, so I do not think that is the answer.\""), .cross("The supplier did give {D} a certificate, didn't they?", "\"Yes, and it says the weld was new. I did not verify when it was issued.\"")],
        defenseRole: "Ride attendant",
        defenseExam: [.direct("What is your role at the ride?", "\"I am an attendant. I load riders, check restraints, and watch the ride during every cycle. I have worked beside {D} for three summers.\""), .direct("Did {D} check the ride regularly?", "\"Not every week. {D.He} checked some parts but not on a fixed schedule, and I never saw a written checklist.\""), .direct("What did you see about a certificate?", "\"The supplier gave {DF} a certificate that I saw taped inside the control box. It said the weld on the support arm was new.\""), .direct("How did the defendant treat safety?", "\"{D.He} cared about riders and always told us to double-check restraints. But {D.he} did not keep up the weekly inspections.\""), .direct("What did you do when the weld failed?", "\"I hit the stop switch and ran to the riders. Some were on the ground, and we called for help.\""), .direct("Did you ever see rust on the weld?", "\"No. I never looked at the weld. That was not my job, and it was high on the arm.\""), .cross("You never inspected the weld, did you?", "\"No. I only run the ride and check restraints.\""), .cross("The certificate you saw was not recent, was it?", "\"I cannot say how recent it was. I saw it in the control box, but I did not read the date.\""), .cross("You did not report any missing checks to anyone, did you?", "\"No. I assumed {DF} had them handled.\""), .cross("You are not an inspector, are you?", "\"No. I am only an attendant, and I rely on the operator.\""), .cross("You would have wanted regular checks done, wouldn't you?", "\"Yes, and I wish I had said something.\"")],
        theory: ("{D} signed off on a failing ride.", "A supplier's certificate."),
        allocution: "\"I trusted the paperwork.\"",
        truths: ("{DL} skipped weekly checks.", "{DL} did get a certificate."),
        defendant: [.direct("What is your role at the fair?", "\"I operate the swing ride and sign the daily inspection sticker. I have run this ride for six summers.\""), .direct("Why did you sign the sticker that day?", "\"I believed the ride was safe, because the supplier had certified the weld as new earlier that season. I checked the harnesses and the motor and signed.\""), .direct("Did you check the ride every week?", "\"Not every week. I checked it when I could and relied on the certificate for the structural parts, which I know was not enough.\""), .direct("What did you see of the weld?", "\"I looked at the arm from the ground and saw nothing wrong. I did not climb up to look at the weld itself.\""), .direct("How are you coping with what happened?", "\"Terrible. Six people were thrown, and I have thought about their faces every night since.\""), .direct("What would you do differently?", "\"I would climb up and inspect every weld weekly and log it. I would never rely on a paper certificate alone.\""), .cross("The maintenance log shows no checks for a year, doesn't it?", "\"Yes, that is what the log shows. I did checks in my head and did not write them down, and I know that is no defense.\""), .cross("You signed the sticker, didn't you?", "\"Yes, I did. I signed because I believed the ride was safe, and I was wrong.\""), .cross("The weld was rusty along the crack, wasn't it?", "\"I have been told that. I did not see the rust, and I did not look closely enough to notice.\""), .cross("A weekly check would have found it, wouldn't it?", "\"Quite possibly. That is what hurts the most.\""), .cross("The supplier's certificate said nothing about checks, did it?", "\"No. It said the weld was new, and I took that to cover the season.\"")],
        openings: ("A swing ride at a county fair threw six riders when a weld failed. The weld was cracked and rusty, {D} signed the inspection sticker, and the log shows no checks for a year. The State will present the state inspector.", "The defense evidence includes an operator who relied on a supplier's certificate that the weld was new, and who did not know it was weak."),
        closings: ("A rusty, cracked weld, a signed sticker, and no checks for a year. Six riders were thrown because no one looked at a part that anyone could see failing.", "{D} trusted a supplier's certificate that the weld was new. The State has not proved {D} knew the weld was failing, and a signature on paper is not knowledge of rust."),
        timeline: [(-365, "Last real check."), (-7, "The certificate."), (0, "The fall."), (20, "Report.")],
        identified: "The failed weld.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let campgroundBluegrassBrawl = SmallCases.make(
        key: "story.campgroundBluegrassBrawl",
        category: .violent,
        headlines: ["Bluegrass Festival Campers Fight Over a Parking Spot, Banjo Used as a Club", "One Man Hospitalized With a Broken Jaw"],
        law: "aisi",
        threshold: 6,
        spec: "Assaulted {V} inflicting serious injury, on or about {DATE}.",
        ages: 21...65,
        victim: true,
        summary: "At a bluegrass festival campground on {DATE}, {D} and {V} argued over a parking spot, and {V} left with a broken jaw. {DL} says {V} swung first with a banjo. The argument began at about 5 p.m. and the fight followed ten minutes later. {V} was treated at a hospital the next day, and two campers say {D} struck first.",
        state: [E(.forensic, 3, "Medical Report", "A broken jaw."), E(.video, 3, "Campground Video", "{D} swings a banjo."), E(.statement, 2, "Witness Statements", "Two campers say {D} struck first.")],
        defense: [E(.video, 1, "Phone Clip", "A clip of {V} lunging first.")],
        role: "Camper",
        exam: [.direct("What did you see at the campground on {DATE}?", "\"{D} and {V} argued over a parking spot at about 5 p.m. About ten minutes later, a fight broke out.\""), .direct("What did you see {DL} do?", "\"{D.He} swung a banjo and struck {V}. {V} left with a broken jaw.\""), .direct("What do the medical records show?", "\"A broken jaw, treated at a hospital the next day. Two campers say {D.he} struck first.\""), .direct("What was the festival like?", "\"A three-day bluegrass festival with about two thousand campers in a field. Everyone has their own spot, and cars are lined up along dusty lanes.\""), .direct("What started the argument?", "\"{DL} and {V} had a heated exchange over a parking spot near a tent. Voices were loud for about ten minutes before it turned physical.\""), .direct("What did you see in the fight?", "\"{D.He} swung a banjo and hit {V} across the face, and {V} went down holding {V.his} jaw. Others rushed in and separated them.\""), .cross("{DL} says {V} swung first, doesn't {D.he}?", "\"I don't recall seeing that. It all happened fast.\""), .cross("Is there a phone clip of {V} lunging?", "\"I'm told there is. I haven't studied it.\""), .cross("Did {DL} step back before swinging?", "\"I don't recall. It was crowded, and I was a bit away.\""), .cross("You did not see the start of the shoving, did you?", "\"No. I was at my own site and turned when the voices got loud.\""), .cross("{V} stepped toward {D} before the swing, didn't {V.he}?", "\"I cannot say for sure. The two were close, and it all happened in a couple of seconds.\"")],
        defenseRole: "Camper",
        defenseExam: [.direct("Did you see the fight?", "\"Yes. I was camped nearby. I saw it start.\""), .direct("Who moved first?", "\"{V}. I saw {V} lunge at {D}. It looked aggressive.\""), .direct("What did {DL} do?", "\"Swung the banjo. It was a reflex.\""), .direct("How did you see this?", "\"I was camped about thirty feet away, and I heard raised voices and turned to look. I saw the whole thing.\""), .direct("What did you see {V} do?", "\"{V} lunged at {DF} with both hands out. It looked like {V} was going to grab or hit {DF}.\""), .direct("What did {D} do in response?", "\"Swung the banjo once in a quick motion and then stepped back, looking stunned. {D.He} did not swing again.\""), .cross("So {DL} swung after {V} backed away?", "\"Yes. That's what I saw. It was only a moment later.\""), .cross("Did you see {V} hit {DL}?", "\"No. I saw a lunge. I didn't see a hit.\""), .cross("Did {V} step back before the swing?", "\"Yes, for a moment, and then {DF} swung. I cannot say whether {DF} saw that.\""), .cross("You did not see what happened before the lunge, did you?", "\"No. I looked over when I heard raised voices and saw {V} lunge first. I do not know what was said in the minutes before that.\""), .cross("You cannot say how many times the defendant swung, can you?", "\"I saw one swing and I turned my head when {V} fell. There may have been another, but I cannot say that I saw one.\"")],
        theory: ("{D} broke a camper's jaw.", "Self-defense."),
        allocution: "\"It got out of hand.\"",
        truths: ("{DL} struck after {V} stepped back.", "{V} lunged first in the clip."),
        defendant: [.direct("How did the fight start?", "\"We argued over a parking spot. It heated up. {V} lunged at me first, and I swung the banjo.\""), .direct("Why a banjo?", "\"It was in my hand. I'd been playing. I used it to protect myself.\""), .direct("Did you mean to break {V}'s jaw?", "\"No. I swung once. I didn't know it would do that. I apologize.\""), .direct("What was happening before the fight?", "\"I was playing my banjo at my campsite and had just parked when {V} told me I was in a reserved spot. I told {V.him} I had not seen any sign.\""), .direct("What did {V} do?", "\"{V} stepped toward me and shouted. Then {V.he} lunged at me, and I felt threatened.\""), .direct("What did you do?", "\"I swung the banjo once, as a reflex. I did not aim at {V.his} jaw, and I did not know what would happen.\""), .cross("The video shows you swinging a banjo, doesn't it?", "\"Yes. It does. I'm not denying that.\""), .cross("You swung after {V} stepped back, didn't you?", "\"It was fast. I may have swung after {V} backed up. I'm not sure.\""), .cross("{V} was left with a broken jaw, wasn't {V.he}?", "\"Yes. I feel awful. I wish I'd walked away.\""), .cross("{V} had stepped back before you swung, hadn't {V.he}?", "\"It is possible. Everything was happening fast, and I am not sure of the order.\""), .cross("A banjo is not a defensive tool, is it?", "\"No. It was in my hand because I had been playing, and I swung it without thinking.\"")],
        openings: ("At a bluegrass festival campground, {D} and {V} argued over a parking spot, and {D} struck {V} with a banjo, breaking {V}'s jaw. Two campers say {D} struck first. The State will show the video and the medical report.", "The defense will point you to a phone clip of {V} lunging first and a camper who saw it. {D} reacted in an instant to a lunge."),
        closings: ("A parking argument, a banjo swung at {V}'s face, and a broken jaw. Two campers say {D} struck first, and a banjo is not something a person swings in a reflex without choosing to.", "The clip shows {V} lunging first, and {D} swung in a reflex as {V} stepped back. The State has not disproved self-defense, and one swing in a crowded field is not a plan to injure."),
        timeline: [(0, "5 p.m.: parking."), (0, "5:10 p.m.: the fight."), (1, "Hospital."), (8, "Arrest.")],
        identified: "Campground video.",
        mood: .divided,
        doctrines: ["selfDefense"],
        genders: ["V": .male])

    static let horseShowTreasurer = SmallCases.make(
        key: "story.horseShowTreasurer",
        category: .whiteCollar,
        headlines: ["County Finance Clerk Siphoned Public Funds to Pay for Show Horses", "Dozens of Trophies and an Empty Account"],
        law: "embezzlement100k",
        threshold: 8,
        spec: "Embezzled over $100,000 of public funds entrusted to {D}, on or about {DATE}.",
        ages: 35...65,
        victim: false,
        summary: "{D}, a county finance clerk, moved $430,000 of public money into a secret account on {DATE} and paid horse show costs. {DL} says the account was a rainy day fund. The first transfer came about five years before the audit. The weekly transfers paid for entry fees and trainer bills, and charges followed ten days after the audit.",
        state: [E(.document, 3, "Secret Account", "Opened by {D}."), E(.digital, 3, "Transfers", "Weekly transfers for years."), E(.document, 3, "Show Receipts", "Entry fees and trainer bills.")],
        defense: [E(.statement, 1, "Rainy Day Memo", "{DL} says a manager knew.")],
        role: "County auditor",
        exam: [.direct("What did your audit find?", "\"$430,000 of public money moved into a secret account opened by {D}. The first transfer came about five years before the audit.\""), .direct("What do the transfers show?", "\"Weekly transfers for years. They went to pay horse show entry fees and trainer bills.\""), .direct("What do the receipts show?", "\"Entry fees and trainer bills for horse shows. Nothing connected to county business.\""), .direct("How did the audit begin?", "\"A routine review of county accounts showed weekly transfers to an account with a name that did not match any department. We traced who opened it.\""), .direct("What did you find?", "\"{D.He} opened the account and made weekly transfers for about five years totaling $430,000. The money was used to pay horse show entry fees and trainer bills.\""), .direct("What were the receipts?", "\"Dozens of receipts for entry fees at regional shows, stall rentals, and trainer fees. Many were in cash.\""), .cross("{DL} says the account was a rainy day fund, doesn't {D.he}?", "\"A manager may have known. I have no formal approval.\""), .cross("Did {DL} hide the account?", "\"It was secret from the audit trail. I found it by following the transfers.\""), .cross("Were the funds all spent?", "\"Most was spent on the horse shows. I can't say every dollar.\""), .cross("A manager did sign a note about a rainy day fund, didn't they?", "\"A vague note, which says nothing about this account or these amounts. It was not an approval.\""), .cross("{D} paid for a horse trailer too, didn't {D.he}?", "\"Yes, a trailer for about $18,000 was bought out of the same account.\"")],
        defenseRole: "Show trainer",
        defenseExam: [.direct("What do you do for work?", "\"I train show horses and teach riding lessons at a small barn. {D} was a client of mine for about five years.\""), .direct("How did {D} pay you?", "\"Mostly in cash after each lesson or show, sometimes by check. I gave receipts for entry fees and training.\""), .direct("How often did you see the defendant?", "\"Several times a week at the barn, and at shows on weekends. {D.He} was serious about riding and always showed up on time.\""), .direct("How much did the defendant spend with you?", "\"Many thousands of dollars over the years, for training, board, and entries. I never added it up at the time.\""), .direct("What did you think about where the money came from?", "\"I assumed it was {D.his} wages and savings. People in this hobby spend a lot, and I did not think anything of it.\""), .direct("What did you do when you heard about the audit?", "\"I pulled my receipts and gave them to the deputies. I told them everything I could remember.\""), .cross("You never asked where the defendant's money came from, did you?", "\"No. I took payments and gave service, and it was not my place to ask.\""), .cross("The amounts were large for a finance clerk's pay, weren't they?", "\"Looking back, yes. I did not do the math as it happened.\""), .cross("{D} never told you it was county money, did {D.he}?", "\"Never. If {D.he} had, I would have refused it.\""), .cross("Many payments were in cash, weren't they?", "\"A lot of them, yes. That was normal at the barn, but it is not a good sign now.\""), .cross("You cannot say whether any of it was a rainy day fund, can you?", "\"No. I only know what {D.he} paid me and what I did with it.\"")],
        theory: ("{D} stole public funds.", "A reserve fund."),
        allocution: "\"I took it a little at a time.\"",
        truths: ("{DL} bought a horse trailer.", "The manager did sign a vague note."),
        defendant: [.direct("Why did the money pay horse show costs?", "\"I used some for those. I thought of it as temporary. I planned to repay it.\""), .direct("Did you steal county money?", "\"No. I intended to put it back. I should have asked first.\""), .direct("What was your job?", "\"County finance clerk for twelve years. I processed transfers and reconciled budget lines.\""), .direct("Why did you open the account?", "\"A manager once told me we should build a small reserve for emergencies. I opened an account and started moving small amounts into it each week.\""), .direct("How did it become horse expenses?", "\"I began using it for shows and training because I had a horse and a tight budget. I told myself I would repay it.\""), .direct("What did you tell your supervisor about the account when it was opened?", "\"I mentioned a reserve fund and said it was for emergencies. I did not provide details, and nobody asked me to document it.\""), .cross("You moved $430,000 into a secret account, didn't you?", "\"Yes. It was a lot. I know it looks bad.\""), .cross("Weekly transfers for five years isn't temporary, is it?", "\"No. It dragged on. I kept telling myself I'd fix it.\""), .cross("The trainer's bills were yours, weren't they?", "\"Yes. I paid for my horse activities from it. I know that's wrong.\""), .cross("You never told anyone about the account, did you?", "\"I mentioned it once to a manager. I did not formally record it.\""), .cross("Five years of weekly transfers is far more than a rainy day fund, isn't it?", "\"It is. I let it grow, and I knew it was wrong by the end.\"")],
        openings: ("{D}, a county finance clerk, moved $430,000 of public money into a secret account over five years and paid horse show costs. The State will present the auditor, the account, and the receipts.", "The defense will present a rainy day fund, a manager who knew, and a clerk who always meant to repay. Listen closely to the witnesses."),
        closings: ("Weekly transfers for years into a secret account, paying entry fees and trainer bills. $430,000 of public money went to horse shows.", "A rainy day fund a manager knew about. The State has not proved {D} meant to keep the money, only that {D} handled it badly."),
        timeline: [(-1800, "First transfer."), (-300, "Trailer purchase."), (0, "Audit."), (10, "Charges.")],
        identified: "Audit file.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let moonshineRunCrash = SmallCases.make(
        key: "story.moonshineRunCrash",
        category: .traffic,
        headlines: ["Driver Fled Deputies on Back Roads With a Truck Full of Jars", "Crash Leaves a Deputy's Car in a Ditch"],
        law: "fleeing",
        threshold: 6,
        spec: "Operated a motor vehicle on a street while fleeing a law enforcement officer, on or about {DATE}.",
        ages: 18...65,
        victim: false,
        summary: "{D} drove a truck loaded with unlicensed liquor jars past a deputy's stop sign on {DATE} and led a chase on back roads until crashing. {DL} says the truck was borrowed and the lights were never seen. The truck ran the stop sign at about 9 p.m. and was in a ditch by 9:12 p.m. The search found jars of clear liquor, and the owner says {DL} borrowed the truck.",
        state: [E(.video, 3, "Dash Camera", "Lights and siren behind the truck."), E(.forensic, 3, "Truck Search", "Jars of clear liquor."), E(.document, 2, "Crash Report", "A ditch and a snapped mailbox.")],
        defense: [E(.statement, 1, "Truck Owner", "The owner says {DL} borrowed it.")],
        role: "Deputy",
        exam: [.direct("What happened at about 9 p.m.?", "\"A truck ran a stop sign past my stop, and I put on my lights and siren. The truck did not stop and led me on a chase.\""), .direct("How long did the chase last?", "\"About twelve minutes on back roads. The truck ended in a ditch by 9:12 p.m. after snapping a mailbox.\""), .direct("What did you see at the stop sign?", "\"A pickup came down the county road at about 9 p.m. and ran the stop sign right in front of my cruiser. I lit up my lights and siren and followed.\""), .direct("How did the chase end?", "\"On a curve, the truck lost control, snapped a mailbox, and slid into a ditch. I approached and found the driver alone in the cab.\""), .direct("What did you find in the truck?", "\"Several jars of clear liquor in the bed under a tarp, and an empty jar on the shoulder a mile back. The jars had no stamps or labels.\""), .direct("What did you see when you reached the truck after the crash?", "\"The driver's door was open and the cab smelled strongly of liquor. Broken glass lay in the ditch, and jars rolled under the seat when I opened the door.\""), .cross("{D} says the lights were never seen, doesn't {D.he}?", "\"Yes. The dash camera shows the lights behind the truck. I cannot say what {D} saw in a mirror.\""), .cross("The owner says the truck was borrowed, doesn't the owner?", "\"Yes. The owner told me {DL} borrowed it. I do not doubt that.\""), .cross("Did you see the defendant throw a jar?", "\"I saw something thrown from the window during the chase. Later I found a broken jar on the road.\""), .cross("The truck belongs to someone else, doesn't it?", "\"Yes. The owner told us {DL} had borrowed it that day.\""), .cross("The dash camera shows your lights from the first second, doesn't it?", "\"Yes, lights and siren from the moment the truck ran the stop sign.\"")],
        defenseRole: "Truck owner",
        defenseExam: [.direct("Did you lend the truck to {D}?", "\"Yes. I lent {D} the truck for a few hours that day. I trusted {D.him} with it.\""), .direct("Did you tell the defendant what was in the bed?", "\"No. I did not mention the cargo. I did not think I needed to, and I wish I had.\""), .direct("Why did you not say anything about the jars?", "\"They were not my business to share. I did not want to get anyone in trouble.\""), .direct("How do you know the defendant?", "\"{DF} is a friend who sometimes borrows my truck. I lent it that afternoon for a few hours.\""), .direct("What was in the truck bed?", "\"A few jars of clear liquor under a tarp, which I had planned to move later. I did not tell {D.him}.\""), .direct("Why did you not mention the jars?", "\"It was not something I wanted to discuss. I assumed {DF} would not look under the tarp.\""), .cross("Did you know the jars were in the truck?", "\"Yes. I knew. It is my truck, and I knew what I had loaded.\""), .cross("Did the defendant know what was in the bed?", "\"I do not think so. {D.He} never asked, and I never said.\""), .cross("Why would you lend the truck loaded with liquor?", "\"I was in a hurry and did not think it through. I now see how it looks.\""), .cross("You knew the jars were in your truck, didn't you?", "\"Yes. I knew what was in the bed.\""), .cross("You lent the truck while it held something unlawful, didn't you?", "\"Yes. I was in a hurry and did not think it through.\"")],
        theory: ("{D} fled from a stop.", "Never saw the lights."),
        allocution: "\"I panicked.\"",
        truths: ("{DL} threw a jar from the window.", "{DL} did not know what was in the bed."),
        defendant: [.direct("Did you run from the deputy on purpose?", "\"No. I did not see the lights until late. When I did, I was scared and kept driving.\""), .direct("Why did you keep going?", "\"I was scared. I did not know what was in the bed, and I did not want trouble.\""), .direct("Did you throw a jar from the window?", "\"I threw something because the wind caught it. I did not mean it as an attack or to hide anything.\""), .direct("How did you get the truck?", "\"I borrowed it that afternoon from the owner to move some furniture. I was told the bed was empty except for a tarp.\""), .direct("What happened at the stop sign?", "\"I did not see the stop sign in time because the sun was in my eyes and the truck's brakes were soft. I rolled through.\""), .direct("When did you see the deputy's lights?", "\"A few seconds later, in the mirror, and I panicked because I had a few drinks in me and the truck was not mine.\""), .cross("The dash camera shows lights and siren behind you for twelve minutes, doesn't it?", "\"It does. I did not notice them at first. By the time I did, I was already committed.\""), .cross("You ran a stop sign and led a chase. How is that not on purpose?", "\"I was frightened. I know it looks bad. I did not intend to flee from law enforcement.\""), .cross("Jars of clear liquor were in the bed. Whose are they?", "\"Not mine. I borrowed the truck and never looked in the bed.\""), .cross("You kept driving for twelve minutes after seeing the lights, didn't you?", "\"Yes. I was afraid and I kept going, which was a terrible decision.\""), .cross("You threw a jar out of the window, didn't you?", "\"I tossed something out in a panic. I did not know what was in the jars.\"")],
        openings: ("A truck ran a deputy's stop sign and led a chase on back roads until it crashed into a ditch, and jars of unlicensed liquor were in the bed. {D} was driving the truck, and a dash camera shows the lights and siren behind it.", "The defense evidence will establish that the truck was borrowed, that {D} did not know what was in the bed, and that {D} noticed the lights too late."),
        closings: ("A stop sign run, lights and siren on camera, a twelve-minute chase, and jars of liquor in the bed. {D} drove away from a deputy, and that is fleeing.", "A borrowed truck, a cargo {D} never knew about, and a driver who saw the lights too late. The State must prove {D} knowingly fled and knew what was inside."),
        timeline: [(0, "9 p.m.: the stop sign."), (0, "9:12 p.m.: the ditch."), (1, "Search."), (15, "Charges.")],
        identified: "A dash camera.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let wrongHouseShot = SmallCases.make(
        key: "story.wrongHouseShot",
        category: .violent,
        headlines: ["Homeowner Fired Through a Door at a Neighbor Who Came to the Wrong House", "Neighbor Hurt Returning From a Night Shift"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon inflicting serious injury, on or about {DATE}.",
        ages: 25...75,
        victim: true,
        summary: "{D} fired through a front door on {DATE} when {V}, a neighbor on a night shift, turned the knob. {V} was wounded. {DL} says {D.he} believed a break-in was under way.",
        state: [E(.forensic, 3, "Medical Report", "A shoulder wound."), E(.video, 3, "Doorbell Camera", "{V} knocks and tries the knob."), E(.forensic, 2, "Ballistics", "One shot through the door.")],
        defense: [E(.statement, 1, "Earlier Break-Ins", "Three recent break-ins on the street.")],
        role: "Detective",
        exam: [.direct("What did {D} do?", "\"{D} fired one shot through the front door. {V} was wounded in the shoulder.\""), .direct("What did ballistics show?", "\"One shot through the door. It matched {D.his} weapon, and the medical report records a shoulder wound.\""), .direct("What was the street like in the weeks before?", "\"Three homes had been broken into over about a month, all at night, and neighbors were frightened. Several residents bought cameras and some bought guns.\""), .direct("What did the doorbell camera show about {V}?", "\"{V} walks up to the door at about two in the morning after a night shift, knocks, and tries the knob. {V} was at the wrong house, two doors from home.\""), .direct("How was {V} wounded?", "\"One round came through the door and struck {V} in the left shoulder. {V} fell back on the porch and called out for help.\""), .direct("What did the doorbell camera show in the minute before the shot?", "\"{V} walked up, knocked twice, and then tried the knob with a keyring in hand. No one called out, and the shot came less than ten seconds after the knob turned.\""), .cross("There had been break-ins in that area, hadn't there?", "\"Yes. Neighbors confirm there had been break-ins. That is real, and I understand why people were afraid.\""), .cross("Did the defendant check the camera before firing?", "\"No. {D.He} did not open the camera app. That is one of the points in this case.\""), .cross("Did the defendant call out before shooting?", "\"{D.He} says {D.he} yelled. The neighbors did not hear a warning.\""), .cross("{V} was tired after a long shift, wasn't {V.he}?", "\"Yes, {V.he} had worked a twelve-hour night shift and said {V.he} thought it was {V.his} own door.\""), .cross("The door was locked, wasn't it?", "\"Yes. {V} found it locked, which is why {V} tried the knob.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Were there break-ins in the neighborhood?", "\"Yes. Several of us had been hit that month. People were scared and slept lightly.\""), .direct("Did you hear a warning before the shot?", "\"No. I did not hear anyone yell. I only heard the shot and then a scream.\""), .direct("How did {D} react afterward?", "\"{D} was in shock and called for help right away. {D.He} looked horrified at what had happened.\""), .direct("How do you know the defendant?", "\"I live two doors down and have for years. We talk across the yard and watch each other's houses.\""), .direct("What had the neighborhood been through?", "\"Three break-ins in a month, including one at my own garage. Everyone locked doors and many bought cameras.\""), .direct("What did you hear that night?", "\"A single loud shot and then a shout for help. I looked out and saw {DF} standing at the open door looking stricken.\""), .cross("Where were you when the shot was fired?", "\"In my home, two doors down. I heard it through the wall and came outside.\""), .cross("Did you hear any shouting from the defendant?", "\"Not that I could make out. It was late, and I might have missed it.\""), .cross("Do you own a gun yourself?", "\"Yes. Many of us bought one after the break-ins. I understand why {D.he} had one.\""), .cross("You did not hear anyone shout a warning before the shot, did you?", "\"I did not, but I was inside and it was late.\""), .cross("Many neighbors own guns since the break-ins, don't they?", "\"Yes, including me. That does not mean any of us should fire without seeing who is there.\"")],
        theory: ("{D} shot a harmless neighbor.", "A fearful homeowner."),
        allocution: "\"I shot without looking.\"",
        truths: ("{DL} did not call out or check the camera.", "Neighbors confirm the break-ins."),
        defendant: [.direct("Did you shoot {V}?", "\"Yes, I fired through the door. I believed a break-in was under way, and I was afraid.\""), .direct("Did you warn the person at the door?", "\"I yelled out. I called for them to leave. I did not hear a reply, and then the knob turned.\""), .direct("Did you check your camera app?", "\"No. I did not open it. I was in a panic, and I did not think of it.\""), .direct("What woke you that night?", "\"A knocking at my front door at two in the morning, then the knob turning. After three break-ins on my street, I was terrified.\""), .direct("What did you do?", "\"I grabbed my pistol from the nightstand and went to the hall. I shouted for whoever it was to leave.\""), .direct("Why did you fire?", "\"I heard the knob rattle again and thought someone was coming in. I fired once through the door without seeing who it was.\""), .cross("You did not see who was at the door, did you?", "\"No. I could not see through the door. I saw only the knob move, and I reacted.\""), .cross("{V} was a neighbor coming home from a night shift. Do you accept that?", "\"I do now. I am sick about it. I did not know it was {V.him}.\""), .cross("You had a camera app and did not look. Why?", "\"I should have, yes. I was terrified and acted on instinct.\""), .cross("You did not look at your camera, did you?", "\"No. I could have glanced at the app and did not.\""), .cross("You fired at a door you could not see through, didn't you?", "\"Yes. I know now that was a terrible decision.\"")],
        openings: ("{V}, a neighbor on a night shift, knocked and tried the knob at the wrong door, and {D} fired one shot through the door, wounding {V} in the shoulder. The doorbell camera recorded the knock.", "By the end of this trial, the proof will show that break-ins were real in that neighborhood, that {D} yelled a warning, and that {D} fired in fear of an intruder."),
        closings: ("A knock on a doorbell camera, a wrong door, and a shot fired without a look at the camera app. {D} could have checked and did not.", "Real break-ins, a locked door at night, and a turning knob. The State must prove {D} did not act out of reasonable fear."),
        timeline: [(-30, "Break-ins begin."), (0, "2 a.m.: the knob."), (0, "2:01 a.m.: the shot."), (1, "911.")],
        identified: "A doorbell camera.",
        mood: .divided,
        doctrines: ["selfDefense"])

    static let nursingHomeNightShift = SmallCases.make(
        key: "story.nursingHomeNightShift",
        category: .violent,
        headlines: ["Night Shift Left a Nursing Home Resident Unchecked for Hours", "Pressure Sores and a Broken Hip"],
        law: "patientNeglect",
        threshold: 7,
        spec: "Having charge of a patient, willfully or recklessly failed to provide care, on or about {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "{V}, a resident, lay in a soiled bed with a broken hip for most of a night shift on {DATE}. {D} was the only aide on the floor. {DL} says six other residents needed help and staffing was short.",
        state: [E(.document, 3, "Care Log", "No checks logged for six hours."), E(.forensic, 3, "Medical Report", "Untreated sores."), E(.video, 2, "Hall Camera", "{D} not seen near the room.")],
        defense: [E(.document, 1, "Staffing Records", "One aide for 26 residents.")],
        role: "State surveyor",
        exam: [.direct("What did you find on the night shift?", "\"{V}, a resident, lay in a soiled bed with a broken hip for most of the shift. The care log shows no checks for six hours.\""), .direct("What did the medical report show?", "\"Untreated sores. {V} had lain too long without being turned or cleaned.\""), .direct("What does the hall camera show?", "\"{D}, the only aide on the floor, was not seen near {V}'s room for hours.\""), .direct("What did you do on the survey?", "\"I toured the unit at night, reviewed charts, and looked at the staffing sheet. We came after a family complaint.\""), .direct("What did {V}'s chart show?", "\"A resident with a broken hip and limited mobility who needed checks every two hours and a reposition. The log had no entries for six hours.\""), .direct("What condition was {V} in?", "\"In a soiled bed with pressure sores forming on the hip and tailbone. {V} had been calling out earlier, according to another resident.\""), .cross("Staffing was short that night, wasn't it?", "\"Yes. Records confirm one aide for 26 residents. I know that is not enough.\""), .cross("Six other residents needed help, didn't they?", "\"Yes. That is what {D.he} says, and I do not dispute it.\""), .cross("Was {D} on a phone break?", "\"{D.He} says so. The break took some time, and that is part of what concerns us.\""), .cross("One aide for 26 residents is a big assignment, isn't it?", "\"It is, and our records confirm that was the staffing that night. It is more than our standard allows.\""), .cross("The home had not replaced the missing staff, had it?", "\"No. Management had cut the night shift two weeks earlier and had not restored it.\"")],
        defenseRole: "Nursing aide",
        defenseExam: [.direct("How many aides were on the floor that night?", "\"One, for 26 residents. That is not safe staffing, and we told management many times.\""), .direct("Did you see {D} take breaks?", "\"Yes, a short phone break. We all did, because no one could get away otherwise.\""), .direct("How long was the phone break?", "\"A short time, maybe fifteen minutes. It was a break during a long night shift.\""), .direct("How do you know about that night?", "\"I worked as an aide on the same floor, in the next hallway. I heard the call lights going off all night.\""), .direct("How was the floor staffed?", "\"One aide for 26 residents, which is far too few. Management had cut the shift without telling us why.\""), .direct("How did the defendant handle it?", "\"{D} ran from room to room, answering call lights as fast as possible. {D.He} looked exhausted by two in the morning.\""), .cross("Did you see the defendant check on {V}?", "\"No. I did not see it. I was on another floor, and I only heard about it later.\""), .cross("Does short staffing excuse six hours without a check?", "\"No. It explains it, but it does not excuse it. A resident should be checked.\""), .cross("Did the defendant report the staffing problem?", "\"I think so. We all did. Management never fixed it.\""), .cross("Short staffing is not a reason to leave someone in a soiled bed, is it?", "\"No. It explains it, but residents still need care.\""), .cross("None of that explains six hours without a check, does it?", "\"It explains why checks slipped, but not all of them. I would not say any aide did the job well on a floor that thin.\"")],
        theory: ("{D} ignored a resident.", "Short staffing."),
        allocution: "\"I was overwhelmed.\"",
        truths: ("{DL} was on a phone break.", "Records confirm one aide for 26 residents."),
        defendant: [.direct("Did you check on {V} that night?", "\"No, I did not. I was the only aide on the floor, and I was running between other residents.\""), .direct("Why did you not check?", "\"I was busy. Six other residents needed help, and I could not be everywhere at once.\""), .direct("What was your night like?", "\"Chaotic. I had six residents who needed help at once, including one who had fallen and one who was choking on a cough.\""), .direct("What did you do about {V}?", "\"I meant to get to {V} after the others. Call lights were going off in every direction.\""), .direct("What about the phone break?", "\"I took a ten-minute break to call my supervisor about staffing. I had asked for help twice and gotten none.\""), .direct("What was the staffing on your floor that night, and what did you do about it?", "\"One aide for twenty-six residents. I asked the charge nurse for help twice and got none, so I went from room to room as fast as I could.\""), .cross("The call light for {V} was on, wasn't it?", "\"I answered others first. I did not get to {V} before the shift was nearly over.\""), .cross("Six hours with no checks. Isn't that neglect?", "\"It is not what I wanted. I did what I could with one aide for 26 people.\""), .cross("A resident lay in a soiled bed with a broken hip. How do you feel about that?", "\"Terrible. I should have found a way, or asked for help sooner.\""), .cross("You did not report the six-hour gap to anyone, did you?", "\"I told my supervisor I was overwhelmed. I did not tell anyone about {V} in particular.\""), .cross("{V}'s call light was on during that time, wasn't it?", "\"Yes. I should have gone sooner, and I live with that.\"")],
        openings: ("{V}, a resident, lay in a soiled bed with a broken hip for most of a night shift. {D} was the only aide on the floor, the care log shows no checks for six hours, and {V} had untreated sores.", "The defense will present evidence that one aide was left to care for 26 residents, that six others needed help, and that short staffing, not choice, caused this."),
        closings: ("Six hours with no checks, untreated sores, and a hall camera that never shows {D} near the room. {V} suffered because no one came.", "One aide for 26 residents, and a floor that no single person could cover. The State must prove {D} knowingly neglected {V}, and understaffing is a failure of management."),
        timeline: [(-7, "Staffing cut."), (0, "Night shift begins."), (0, "5 a.m.: resident found."), (8, "State survey.")],
        identified: "A care log.",
        mood: .sympathetic,
        doctrines: ["burdenOfProof"])

    static let kittenFoodBurglars = SmallCases.make(
        key: "story.kittenFoodBurglars",
        category: .property,
        headlines: ["Pair Hit Nine Homes by Posing as Pet Sitters", "Owners Return to Missing Cash and Jewelry"],
        law: "felonyLarceny",
        threshold: 7,
        spec: "Took and carried away property of {V} worth over $1,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} advertised as a pet sitter and was given keys by nine owners. Items disappeared from each home, including about $6,000 of jewelry and cash from {V}'s on {DATE}. {DL} says a partner took items without {D.him} knowing.",
        state: [E(.digital, 3, "Sitter Listing", "Keys exchanged with nine owners."), E(.forensic, 3, "Pawn Records", "Items sold by {D}'s ex."), E(.video, 2, "Door Cameras", "{D} alone inside.")],
        defense: [E(.statement, 1, "Partner Note", "A note naming a partner.")],
        role: "Homeowner",
        exam: [.direct("What did you give {DL}?", "\"A key to my home. {D} advertised as a pet sitter, and I trusted {D.him} with my house and my pet.\""), .direct("What went missing?", "\"About $6,000 of jewelry and cash from my home. I found it gone after {DATE}.\""), .direct("What do the door cameras show?", "\"{D.He} alone inside my house. And pawn records show items sold by {D.his} ex.\""), .direct("How did you find {D}?", "\"I saw a flyer for a pet sitter at the vet and called. {DL} came over, met my cat, and I gave {DL} a key for a week while I traveled.\""), .direct("What did you find when you returned?", "\"The cat was fine and the house looked tidy, but my jewelry box was empty and cash from a drawer was gone. Other homes had the same experience.\""), .direct("What did your door camera show?", "\"{D.He} enters with a key, spends a while in the bedroom and the kitchen, and leaves with a tote bag. No one else is seen on that footage.\""), .cross("{DL} says a partner took items without {D.him} knowing, doesn't {D.he}?", "\"There was a note naming a partner. I can't say who took what.\""), .cross("Did you see {DL} take anything?", "\"No. I saw {D.him} on camera inside. I didn't see anything taken.\""), .cross("Did anyone else have a key?", "\"Not that I know. I gave it to {DL} only.\""), .cross("You never saw the jewelry leave, did you?", "\"No. I only saw {DL} carry a bag out.\""), .cross("Nine owners gave the defendant keys, didn't they?", "\"Yes. All of us reported items missing within weeks.\"")],
        defenseRole: "Pawn clerk",
        defenseExam: [.direct("What is your job?", "\"I am a clerk at a pawn shop. I record the seller's ID and each item on a ticket.\""), .direct("Who sold the pieces from these homes?", "\"A person I recognized from other visits, who came in several times with rings and watches. I logged each sale.\""), .direct("Did {D} ever come to your counter?", "\"No. I do not remember {D} coming in at all.\""), .direct("What did the seller tell you about the items?", "\"That they were family pieces and the family needed money. People say that often, and I did not think much about it.\""), .direct("How did the seller appear to you?", "\"Calm and quick, and always alone. The seller never mentioned another person.\""), .direct("What did you do when the deputies came?", "\"I pulled the tickets and gave them photocopies. I showed them the seller's ID.\""), .cross("You did not check whether the items were stolen, did you?", "\"No. I check IDs and serial numbers, but I did not know these pieces had been reported.\""), .cross("You cannot say who was with the seller outside, can you?", "\"No. I only see who comes to the counter.\""), .cross("The seller and the defendant may know each other, mightn't they?", "\"They may. I would not know that.\""), .cross("Pawn shops see stolen items sometimes, don't they?", "\"Yes, and that is why we keep records.\""), .cross("You never saw the defendant with the seller, did you?", "\"Never. Not once, in the shop or outside.\"")],
        theory: ("{D} used keys to steal.", "A partner stole."),
        allocution: "\"I trusted the wrong person.\"",
        truths: ("{DL} was alone on every camera.", "The partner's note is unsigned."),
        defendant: [.direct("Did you take items from the homes?", "\"No. I never took anything. I took care of pets.\""), .direct("Who took them?", "\"My partner. I let my partner into the homes a few times. I didn't know what they took.\""), .direct("Why were you alone on the cameras?", "\"Because I was doing my job with the pets. My partner came another time.\""), .direct("How did you take care of the pets?", "\"I visited twice a day, fed them, walked the dogs, and sent photos. I was careful with every animal.\""), .direct("Who was your partner?", "\"A person I lived with at the time, who sometimes came along. I let my partner in a few times when I was running late.\""), .direct("What did you notice about the missing items?", "\"Nothing at the time. I only heard when owners called me angry, and I was horrified.\""), .cross("Nine owners gave you keys, didn't they?", "\"Yes. I took the pet-sitting job seriously. I don't know how things went missing.\""), .cross("You let someone into those homes, didn't you?", "\"Yes. I shouldn't have. That was a breach of trust.\""), .cross("You let someone into customers' homes without asking, didn't you?", "\"Yes. It was a breach of trust, and I should not have done it.\""), .cross("Your partner sold items at a pawn shop, didn't {V.he}?", "\"Yes. I did not know where the items came from, and I never asked.\""), .cross("The cameras show nobody inside but you, don't they?", "\"That is true. I was alone when I was inside. I still say someone else took items on other days, but I understand the cameras are hard evidence.\"")],
        openings: ("{D} advertised as a pet sitter and was given keys by nine owners. About $6,000 in jewelry and cash vanished from {V}'s home, and {D} is alone inside on the door cameras. The State will present the homeowner and the pawn records.", "The defense will present items sold at a pawn shop by a partner, a pawn clerk who never saw {D}, and a sitter who did not know."),
        closings: ("Nine keys, items missing from every home, and {D} alone inside on camera. People trusted {D} with their homes and pets, and the jewelry and cash went missing from each one.", "The pawn clerk saw the partner, not {D}. The State has not proved {D} took anything or knew about what a partner did, and a note naming a partner raises a real doubt."),
        timeline: [(-90, "The listing."), (0, "Visit to {V}'s home."), (14, "Items found missing."), (40, "Pawn match.")],
        identified: "Door cameras.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let grandchildCallerScheme = SmallCases.make(
        key: "story.grandchildCallerScheme",
        category: .whiteCollar,
        headlines: ["Caller Posed as a Grandson in Jail to Get Bail Money From Seniors", "Nine Elderly Victims Lose $120,000"],
        law: "exploitationElder",
        threshold: 8,
        spec: "Knowingly obtained the funds of {V}, an older adult, through deception, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} picked up cash from nine seniors who got calls from a 'grandson' needing bail, including from {V} on {DATE}. {DL} says {D.he} was a courier who did not know the calls were lies. {V} handed over $14,000. The ninth pickup came a week later, and the arrest followed five days after that.",
        state: [E(.digital, 3, "Call Logs", "Calls to nine seniors."), E(.video, 3, "Doorstep Camera", "{D} collects an envelope."), E(.document, 2, "Wire Receipts", "Cash forwarded out of state.")],
        defense: [E(.statement, 1, "Courier Ad", "{DL} answered a job ad.")],
        role: "Detective",
        exam: [.direct("What did you learn about the scheme?", "\"Nine seniors got calls from someone posing as a grandchild needing bail money. {D} picked up the cash. One of them was {V}, who handed over $14,000.\""), .direct("What does the doorstep camera show?", "\"It shows {DL} collecting an envelope. The ninth pickup came a week later, and we arrested {DL} five days after that.\""), .direct("Where did the cash go?", "\"Wire receipts show cash forwarded out of state. That's the typical path in this kind of scheme.\""), .direct("How did the calls work?", "\"A caller said they were a grandchild in jail and needed bail money right away, and begged the senior not to tell anyone. A second person posing as a lawyer then gave instructions.\""), .direct("What did {V} do?", "\"{V} withdrew $14,000 in cash from the bank and handed it to a courier at the door. {V} was told to expect a person at the home that afternoon.\""), .direct("How did you link {D}?", "\"The doorstep camera shows {DL} taking an envelope, and wire receipts show cash forwarded out of state afterward. {DL} made nine pickups across a week.\""), .cross("{DL} says {D.he} was a courier who did not know, doesn't {D.he}?", "\"{D.He} answered a job ad. I can't read {D.his} mind.\""), .cross("Did {DL} make the calls?", "\"No. The calls came from others. {D.He} picked up envelopes.\""), .cross("How many pickups did {DL} make?", "\"Nine. Over about a week. I'd say that's a lot for an ordinary courier.\""), .cross("{D} did not make any of the calls, did {D.he}?", "\"No. The calls came from other phones. {D.He} was the one who showed up.\""), .cross("{D} answered a job ad, didn't {D.he}?", "\"Yes. The ad promised easy pay for picking up and forwarding envelopes.\"")],
        defenseRole: "Victim's neighbor",
        defenseExam: [.direct("Are you {V}'s neighbor?", "\"Yes. I live next door. I check on {V} often.\""), .direct("Was {V} confused?", "\"Yes. {V} is easily confused. The call frightened {V}.\""), .direct("How do you know {V}?", "\"I live next door and check on {V} most days. {V} is a gentle person who gets easily confused.\""), .direct("What happened that day?", "\"{V} told me a grandchild was in jail and needed bail. I tried to talk {V} out of it and called a relative, but {V} went to the bank.\""), .direct("What did you see at the door?", "\"Later that afternoon a person came to {V}'s door and took an envelope. It was quick and quiet, and the person left on foot.\""), .direct("What did you say to {D} after the envelope was handed over?", "\"I asked if everything was all right. {D} said it was a pickup for a family emergency and left quickly without giving a name.\""), .cross("Did {DL} tell {V} anything?", "\"I don't know. I only saw {DF} at the door. I don't know what was said.\""), .cross("Was the courier told it was a scheme?", "\"Unknown. I can't say what {D.he} knew.\""), .cross("Did you see {DL} take the envelope?", "\"Yes. I saw it. It was quick.\""), .cross("You did not hear what the defendant said to {V}, did you?", "\"No. I was across the yard.\""), .cross("You cannot say what the defendant knew, can you?", "\"No. I only saw {DF} take the envelope.\"")],
        theory: ("{D} collected money for the scam.", "An unwitting courier."),
        allocution: "\"I knew it was strange.\"",
        truths: ("{DL} made nine pickups in a week.", "The ad promised easy pay."),
        defendant: [.direct("What was your job?", "\"A courier. I answered an ad and picked up envelopes. I was told they were legal documents.\""), .direct("Did you know about the calls?", "\"No. I never knew seniors were being scammed. I'd never hurt an older person.\""), .direct("What did you do with the cash?", "\"I forwarded it as instructed. I thought I was doing my job.\""), .direct("How did you get the job?", "\"I answered an online ad for a courier, easy pay, flexible hours. A person texted me addresses and times.\""), .direct("What did you do at the doors?", "\"I rang the bell, took an envelope, and wired the contents as instructed. I took a cut for myself.\""), .direct("What did you think the money was?", "\"I thought it was business payments from a small company. I never opened the envelopes.\""), .cross("You picked up nine envelopes, didn't you?", "\"Yes. I did. I thought it was strange but I did it.\""), .cross("The envelopes had cash, didn't they?", "\"I didn't open them. I never looked. I know I should have.\""), .cross("You forwarded it out of state, didn't you?", "\"Yes. That was part of the job. I didn't ask why.\""), .cross("Nine pickups in a week from older people is odd, isn't it?", "\"Looking back, it is. I thought it was strange but I needed the pay.\""), .cross("You were told to forward cash out of state, weren't you?", "\"Yes. I did not think about why.\"")],
        openings: ("{D} picked up cash from nine seniors who received calls from someone posing as a grandchild needing bail, including $14,000 from {V}. The doorstep camera shows {D}. The State will present the detective and the records.", "Jurors will also see a courier who answered a job ad, never opened an envelope, and did not know the calls were lies. Listen closely to the witnesses."),
        closings: ("Nine pickups, nine seniors, and $14,000 from {V}. {D} collected envelopes of cash from frightened older people and forwarded it out of state.", "A courier who answered an ad and did not know what was inside the envelopes. The State has not proved {D} knew the calls were lies, and no one told {D} what the envelopes held."),
        timeline: [(-14, "Calls begin."), (0, "{V} hands over $14,000."), (7, "Ninth pickup."), (12, "Arrest.")],
        identified: "Doorstep camera.",
        aggravating: ["The victim was particularly vulnerable", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let bakeryInsuranceBlaze = SmallCases.make(
        key: "story.bakeryInsuranceBlaze",
        category: .property,
        headlines: ["Bakery Owner Accused of Setting a Fire After Missed Payments", "Fuel Trail and an Overdue Policy Claim"],
        law: "burningBuildings",
        threshold: 8,
        spec: "Willfully and wantonly burned a building, on or about {DATE}.",
        ages: 25...70,
        victim: false,
        summary: "A bakery owned by {D} burned overnight on {DATE}. Investigators found a fuel trail. {DL} says an oven fault started it.",
        state: [E(.forensic, 3, "Fire Marshal Report", "A fuel trail."), E(.document, 3, "Loan Notices", "Three missed payments."), E(.document, 2, "Claim Form", "A $380,000 claim filed that day.")],
        defense: [E(.forensic, 1, "Oven Service", "A recent oven repair report.")],
        role: "Fire marshal",
        exam: [.direct("What did you find at the bakery on {DATE}?", "\"It burned overnight. I found a fuel trail. That is evidence of an intentionally set fire.\""), .direct("What did the loan notices show?", "\"Three missed payments. {D}'s finances were under strain.\""), .direct("What about the insurance claim?", "\"A $380,000 claim was filed that same day. That speed is unusual.\""), .direct("How do you investigate a fire?", "\"I examine the burn pattern, the origin point, and the utilities. A fuel trail shows up as a path of heavy char leading to where the fire started.\""), .direct("What did you find at the bakery?", "\"A trail of char from the back door to the front counter, with traces of an accelerant. The oven area showed damage, but not the deepest burn.\""), .direct("What about the timeline?", "\"The fire alarm came at midnight, and the claim form was filed that same day by {DL}. That is unusually fast.\""), .cross("{DL} says an oven fault started it, doesn't {D.he}?", "\"Ovens can cause fires. But a fuel trail is not something an oven makes.\""), .cross("Did anyone see {DL} start the fire?", "\"No. No one saw it. I rely on the physical evidence and the finances.\""), .cross("Could the fuel trail have another source?", "\"I considered that. I found nothing in the bakery that would explain it.\""), .cross("The oven had a service flag, didn't it?", "\"Yes, a service ticket from the week before. That could mean a fault, though it does not explain a trail.\""), .cross("Some equipment had been removed from the bakery two days earlier, hadn't it?", "\"Yes, {D.he} had removed a mixer and a proofing cabinet. {D.He} says it was for repair.\"")],
        defenseRole: "Baker",
        defenseExam: [.direct("Do you work at the bakery?", "\"Yes. I'm a baker there. I know the equipment well.\""), .direct("Was any gear removed before the fire?", "\"Yes. Some equipment had been taken out to be repaired and cleaned.\""), .direct("What about the oven?", "\"It had been acting up and had been serviced recently. It was a worry for all of us.\""), .direct("What is your job?", "\"I am a baker, and I worked next to {D} at the bakery for six years. I know the ovens and the mixers.\""), .direct("What did you notice about the oven?", "\"It ran hot and the thermostat cut out. We had a repairman look at it a few days before the fire.\""), .direct("Was equipment removed?", "\"Yes, a mixer and a cabinet went out for service a couple of days before. {D.He} told us it was routine.\""), .cross("When was the oven serviced?", "\"Last week, I believe. I don't have the exact day.\""), .cross("Did the service fix the problem?", "\"I thought so. It still ran hot sometimes. I can't say it was perfect.\""), .cross("Did you see anything about a fuel trail?", "\"No. I never saw one. I only know about the oven.\""), .cross("The repair did not fix everything, did it?", "\"It helped, but the oven still ran hot at times.\""), .cross("You cannot say how the fire started, can you?", "\"No. I was home asleep when it burned.\"")],
        theory: ("{D} burned the bakery.", "An oven fault."),
        allocution: "\"I was out of options.\"",
        truths: ("{DL} removed equipment two days earlier.", "The oven had a service flag."),
        defendant: [.direct("Did you burn your bakery?", "\"No. It was my life's work. I'd never destroy it.\""), .direct("What do you think started the fire?", "\"An oven fault. The oven had been acting up, and I'd had it serviced recently.\""), .direct("Why did you file the claim so quickly?", "\"I needed to know what to do. The agent told me to file right away. I followed the advice.\""), .direct("How long had you owned the bakery?", "\"Eleven years. I built it from nothing and baked every morning at four.\""), .direct("What was wrong with the oven?", "\"It ran hot and tripped the breaker a few times. A tech serviced it a week before the fire, but it still acted up.\""), .direct("Why did you remove equipment?", "\"The mixer and proofing cabinet were being serviced at a shop. I planned to bring them back the next week.\""), .cross("You missed three loan payments, didn't you?", "\"Yes. Business was slow. But that's not why the fire happened.\""), .cross("You filed a $380,000 claim the same day, didn't you?", "\"Yes. I did it on the agent's advice. I was in shock.\""), .cross("A fuel trail was found, wasn't it?", "\"That's what they say. I don't know how it got there.\""), .cross("You moved equipment out two days before the fire, didn't you?", "\"Yes. I took the older mixer to a friend's shop because the lease was ending, and I said so in my notes. I understand how the timing looks.\""), .cross("You filed the claim the same day, before the investigators finished, didn't you?", "\"I called the insurance company that morning because I needed to protect my rights. I did not know the fire marshal had not finished.\"")],
        openings: ("A bakery owned by {D} burned overnight, and investigators found a fuel trail. {D} had missed three loan payments and filed a $380,000 claim that same day. The State will present the fire marshal.", "The defense evidence includes an oven that was acting up, a recent service report, and an owner who lost everything. Listen closely to the witnesses."),
        closings: ("A fuel trail, three missed loan payments, and a $380,000 claim filed that very day. The evidence points to a fire set by someone who needed money, not an oven fault.", "An oven fault is a likelier explanation than arson. The State has not proved {D} set the fire, and a baker who removed equipment for repair and filed a claim on an agent's advice acted like an owner, not an arsonist."),
        timeline: [(-90, "Missed payments."), (-2, "Gear removed."), (0, "Midnight fire."), (1, "Claim filed.")],
        identified: "Fire report.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let fentanylSalineSwap = SmallCases.make(
        key: "story.fentanylSalineSwap",
        category: .drugs,
        headlines: ["Nurse Replaced Painkillers With Saline for Months", "Patients Left in Pain While Pills Went Missing"],
        law: "prescriptionFraud",
        threshold: 7,
        spec: "Obtained a controlled substance by fraud, deceit and misrepresentation, on or about {DATE}.",
        ages: 25...60,
        victim: false,
        summary: "{D}, a hospital nurse, signed out fentanyl vials for patients and replaced contents with saline for months, including on {DATE}. {DL} says a disposal error explains the numbers. Sign-outs began rising about six months earlier. A patient complained, the vials tested as saline two weeks later, and charges followed thirty days after that.",
        state: [E(.forensic, 3, "Vial Testing", "Saline in sealed vials."), E(.document, 3, "Dispensing Logs", "{D} signs out twice the average."), E(.digital, 2, "Badge Records", "Visits to the supply room.")],
        defense: [E(.statement, 1, "Disposal Note", "Wasting rules were changed.")],
        role: "Pharmacy director",
        exam: [.direct("What did vial testing find at the hospital?", "\"Saline in sealed vials that should have held fentanyl. A patient complained of pain, and the vials tested as saline two weeks later.\""), .direct("What do the dispensing logs show?", "\"{D}, a nurse, signed out twice the average. The sign-outs began rising about six months earlier and continued on {DATE}.\""), .direct("What do the badge records add?", "\"Repeated visits to the supply room by {DL}. The pattern lines up with the sign-outs.\""), .direct("What is your role?", "\"Director of pharmacy for the hospital. I track every controlled substance from the vault to the patient.\""), .direct("How did this come to light?", "\"A patient reported that pain medicine was not working. We tested vials returned from that unit and found saline in sealed fentanyl vials.\""), .direct("What did the logs show?", "\"{DL} signed out about twice the unit average for months. Badge records show repeated visits to the supply room by {DL}, often near shift end.\""), .cross("{DL} says a disposal error explains the numbers, doesn't {D.he}?", "\"Wasting rules were changed, which can create confusion. But saline in sealed vials is not a disposal error.\""), .cross("Who else had access to the supply room?", "\"Other nurses did. Access was not exclusive to {D.him}. I can't say no one else touched those vials.\""), .cross("Did anyone see {DL} swap a vial?", "\"No. No one did. I rely on the logs, the badge data, and the testing.\""), .cross("Disposal rules did change that year, didn't they?", "\"Yes, wasting procedures were revised, which caused some confusion on the units.\""), .cross("Other nurses had badge access, didn't they?", "\"Yes. About thirty nurses had access, and the pattern still pointed to {D.him}.\"")],
        defenseRole: "Charge nurse",
        defenseExam: [.direct("Do you supervise {DL}?", "\"Yes. I'm a charge nurse. I see how the unit works.\""), .direct("Did others have access to the supply room?", "\"Yes. Many nurses had badge access. It's a busy unit.\""), .direct("Were the wasting rules changed?", "\"They were. There was confusion for a while about how to document disposal.\""), .direct("How do you supervise {D}?", "\"I am the charge nurse on the unit and review assignments and sign-outs each shift. I work beside the nurses all night.\""), .direct("What did you notice about the defendant's sign-outs?", "\"They were high, but {D}'s patients were heavy on pain management. I did not think much of it at the time.\""), .direct("How did the wasting change affect the unit?", "\"We switched to a new form and a new witness rule, and for weeks nobody was sure who should sign. There were mistakes.\""), .cross("Did other nurses sign out the same amounts?", "\"No. {D.his} numbers were higher. I can't say others had the same pattern.\""), .cross("Did you see {DL} replace a vial?", "\"No. I only know about the unit.\""), .cross("Could the rules explain saline in a sealed vial?", "\"I don't see how. That is a different issue. I can't explain that.\""), .cross("Other nurses did not sign out as much, did they?", "\"No. {D.his} numbers stood out, and that is why I asked questions.\""), .cross("The rule change would not explain saline in a sealed vial, would it?", "\"No, I do not see how. That is a different problem.\"")],
        theory: ("{D} took pills and swapped vials.", "A paperwork error."),
        allocution: "\"I was in trouble myself.\"",
        truths: ("{DL} had a prescription lapse.", "Others also had access."),
        defendant: [.direct("Why did you sign out so much fentanyl?", "\"My patients needed it. I had a heavy load of patients in pain. I signed out what the orders called for.\""), .direct("How do you explain saline in the vials?", "\"I don't. Wasting rules changed, and there was confusion about disposal. I never replaced anything.\""), .direct("Did you take fentanyl?", "\"No. I never took any for myself or anyone else. I would never harm a patient.\""), .direct("What was your patient load?", "\"Several post-surgical and cancer patients who needed frequent doses. My unit was always short-staffed.\""), .direct("How did you handle wasting?", "\"I returned unused portions to the nurse who witnessed it. When the rules changed, we were confused about who was to sign.\""), .direct("What do you say about the saline?", "\"The saline puzzles me as much as anyone, because I never opened a sealed vial.\""), .cross("You signed out twice the average, didn't you?", "\"Yes. I had more patients on that medication. I don't think it means I did anything wrong.\""), .cross("You visited the supply room often, didn't you?", "\"Yes. It's part of my job. Everyone goes there.\""), .cross("Patients complained of pain, didn't they?", "\"I understand so. I'm so sorry. I gave them what was in the vials.\""), .cross("You had a prescription lapse around that time, didn't you?", "\"Yes, for a medication of my own, and I was struggling. I did not take the hospital's fentanyl.\""), .cross("You were the one person who signed out fentanyl more than anyone else on the floor, weren't you?", "\"I had the heaviest patient load and I signed out for pain management. I understand the numbers look high, and I cannot explain every vial.\"")],
        openings: ("{D}, a hospital nurse, signed out fentanyl at twice the average rate for months, and vials tested as saline. Badge records show visits to the supply room. The State will present the pharmacy director and the testing.", "The defense will point you to a busy unit where many nurses had access, disposal rules that changed, and no witness who saw {D} swap anything. Listen closely to the witnesses."),
        closings: ("Saline in sealed vials, twice the average sign-outs, and repeated supply room visits by {D}. Patients in pain received water because someone took the real medicine.", "Many nurses had access and the wasting rules were changing. The State has not proved {D} replaced a single vial, and a paperwork error is a real explanation for numbers that look strange."),
        timeline: [(-180, "Sign-outs rise."), (0, "A patient complains."), (14, "Vials tested."), (30, "Charges.")],
        identified: "Dispensing logs.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let clinicWithoutLicense = SmallCases.make(
        key: "story.clinicWithoutLicense",
        category: .whiteCollar,
        headlines: ["Man Ran a 'Wellness Clinic' With No Medical Training", "Patients Paid for Injections and Scans"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained money from {V} and others by false pretenses, on or about {DATE}.",
        ages: 28...65,
        victim: true,
        summary: "{D} ran a storefront clinic on {DATE}, charging patients like {V} for injections and fake scans. {DL} says a licensed doctor, now gone, supervised. A complaint reached the health department about six weeks after {V}'s visit, and the department closed the clinic about five months after it opened, by which time it had collected about $60,000.",
        state: [E(.document, 3, "License Search", "No license on file."), E(.forensic, 3, "Injection Records", "Unlabeled vials."), E(.document, 2, "Billing", "$60,000 collected.")],
        defense: [E(.document, 1, "Supervisor Letter", "A letter from a doctor.")],
        role: "Health inspector",
        exam: [.direct("What did you find at the storefront clinic?", "\"No license on file for {D}. The clinic was charging patients for injections and scans without any license.\""), .direct("What did the injection records show?", "\"Unlabeled vials. Nobody could say what was being injected into patients like {V}.\""), .direct("How did the complaint come to you?", "\"{V} wrote to the department about a visit to a storefront clinic, where injections and a scan cost hundreds of dollars. {V} said there was no doctor in sight.\""), .direct("What did you find at the clinic?", "\"A converted storefront with an exam table, a refrigerator of unlabeled vials, and an old ultrasound machine. A sign on the door said medical services.\""), .direct("What did the billing show?", "\"About $60,000 collected over roughly five months from patients paying cash and card. Most charges were for injections and scans.\""), .direct("What did you do when you found the clinic had no licensed doctor on site?", "\"We closed the storefront the same day, secured the records and the vials, and notified the medical board. Patients were told to see a licensed provider.\""), .cross("{DL} says a licensed doctor supervised, doesn't {D.he}?", "\"There's a letter from a doctor. I couldn't confirm the doctor was ever present.\""), .cross("Did {DL} treat patients personally?", "\"I understand that {D.he} did the injections. Whether the doctor saw patients is unclear.\""), .cross("Were patients seriously hurt?", "\"I can't say. I know {V} complained. I don't have a record of serious injury.\""), .cross("A letter from a doctor said that doctor supervised, didn't it?", "\"Yes, and the doctor's license had lapsed before the clinic opened.\""), .cross("You did not confirm that {V} was harmed, did you?", "\"No. I know {V} paid for treatment that no licensed person gave.\"")],
        defenseRole: "Front desk worker",
        defenseExam: [.direct("Did you work at the clinic?", "\"Yes. I was the front desk worker. I scheduled patients and took payments.\""), .direct("Did you see a doctor?", "\"Once. A doctor came by one time. I didn't see the doctor again.\""), .direct("Who did the injections?", "\"{D}. I saw {DF} prepare and give them.\""), .direct("What was your job at the clinic?", "\"I worked the front desk, scheduling patients and taking payments. I was there nearly every day for four months.\""), .direct("How many times did you see a doctor there?", "\"Once, for a short visit early on. I never saw the doctor again after the second month.\""), .direct("Who did the injections and scans?", "\"{DF}. I watched {DF} prepare vials and use the scanner on patients most days.\""), .cross("Did the doctor sign the letter?", "\"Unsure. I never saw the doctor sign. I only saw the letter.\""), .cross("Did the doctor supervise?", "\"I can't say that. I never saw supervision.\""), .cross("Did patients get their money's worth?", "\"I don't know. I handled payments. I can't speak to treatment.\""), .cross("You never saw anyone supervising {D}, did you?", "\"No. I saw no supervision in all the time I was there.\""), .cross("You handled payments of tens of thousands of dollars, didn't you?", "\"Yes, mostly cash and cards. I did not think about the total.\"")],
        theory: ("{D} posed as medical staff.", "A supervising doctor."),
        allocution: "\"I only wanted to help.\"",
        truths: ("{DL} billed under another name.", "The doctor's license lapsed."),
        defendant: [.direct("Why did you run the clinic?", "\"I wanted to help people who couldn't afford a regular clinic. A licensed doctor supervised, and I handled the day-to-day.\""), .direct("Where is the doctor now?", "\"Gone. The doctor left before the health department came. I can't reach the doctor anymore.\""), .direct("Did you inject patients?", "\"Yes, under the doctor's supervision. I thought that was allowed. I never claimed to be a doctor.\""), .direct("How did the clinic start?", "\"I opened it to serve neighbors who could not afford the hospital. I partnered with a doctor who said I could give injections under supervision.\""), .direct("What did you give patients?", "\"Vitamin shots and injections for pain, and I did scans with a handheld ultrasound I bought. I was told it was allowed.\""), .direct("What happened to the doctor?", "\"The doctor stopped coming around the third month and then left. I could not reach the doctor after that.\""), .cross("You have no license, do you?", "\"No. I don't. I relied on the doctor's license.\""), .cross("You charged patients for scans, didn't you?", "\"Yes. They weren't medical scans in the usual sense. I know that sounds bad.\""), .cross("You collected $60,000, didn't you?", "\"About that. Most went to costs. I know it's a lot.\""), .cross("You do not have a license of any kind, do you?", "\"No. I never claimed one, but I let patients think I was staff.\""), .cross("The vials were unlabeled, weren't they?", "\"Yes, some were. I made the mistake of relabeling in a hurry.\"")],
        openings: ("{D} ran a storefront clinic with no license, charging patients like {V} for injections from unlabeled vials and for fake scans, and collected about $60,000. The State will present the health inspector and the records.", "The defense will present a licensed doctor who {D} says supervised, a letter from that doctor, and a clinic run openly. Listen closely to the witnesses."),
        closings: ("No license, unlabeled vials, fake scans, and $60,000 collected from patients. {D} practiced medicine without a license and charged people who trusted a storefront sign.", "{D} says a licensed doctor supervised, and a letter says so. The State has not proved {D} knew the doctor's license had lapsed, and a patient list and receipts show {D} was open about the business."),
        timeline: [(-90, "Doors open."), (0, "{V} is treated."), (40, "Complaint."), (60, "Closure.")],
        identified: "Billing records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fakeIllnessFundraiser = SmallCases.make(
        key: "story.fakeIllnessFundraiser",
        category: .whiteCollar,
        headlines: ["Online Fundraiser for a Made-Up Illness Raised Thousands", "Donors Find No Hospital Records"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained money from donors by false pretenses, on or about {DATE}.",
        ages: 20...60,
        victim: false,
        summary: "{D} posted a fundraiser on {DATE} claiming a rare illness, with photos from another patient, and received $27,000. {DL} says the diagnosis was real but records were lost. Donations passed $20,000 about ten days after the page went up, and a donor began investigating about six weeks after that.",
        state: [E(.digital, 3, "Fundraiser Page", "Photos from a stranger's account."), E(.document, 3, "Hospital Reply", "No records for {D}."), E(.digital, 2, "Transfers", "$27,000 into {D}'s account.")],
        defense: [E(.statement, 1, "Doctor's Note", "{DL} shows a note from a clinic.")],
        role: "Donor",
        exam: [.direct("Why did you give to {DL}'s fundraiser?", "\"{D} posted that {D.he} had a rare illness. It touched me, and I donated. Donations passed $20,000 within ten days.\""), .direct("What did you later learn?", "\"The photos came from a stranger's account. The hospital said it had no records for {D.him}.\""), .direct("How much did {DL} receive?", "\"$27,000 transferred into {D.his} account. The transfers are in evidence.\""), .direct("How did you see the fundraiser?", "\"A friend shared the page online. It had a long story about a rare autoimmune illness, photos of a hospital bed, and a goal of $30,000 for treatment.\""), .direct("What did you give?", "\"$200, with a note of encouragement. I and other friends gave about $20,000 within ten days, and I felt good about helping.\""), .direct("What made you start looking into it?", "\"A reverse image search showed the hospital photos belonged to another person's page in a different state. I called the hospital named on the page.\""), .cross("{DL} says the diagnosis was real, doesn't {D.he}?", "\"I can't prove otherwise. I only know the hospital had no records.\""), .cross("Did you check before giving?", "\"No. I trusted the page. I began investigating only after hearing doubts.\""), .cross("Did {DL} show any records?", "\"A note from a clinic. I haven't been able to verify it.\""), .cross("You do not know whether {D} was actually ill, do you?", "\"No. I only know the hospital told me they had no records of {DL}.\""), .cross("The clinic note is real, isn't it?", "\"I have been told it is genuine, but it has no date and does not name a rare illness.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Do you know {DL}?", "\"Yes. We're friends. I saw {D} around that time.\""), .direct("Did {DL} look ill?", "\"Not to me. {D.He} seemed fine. I didn't notice anything.\""), .direct("What did {DL} tell you?", "\"That there was a diagnosis and bills. I took {D.his} word.\""), .direct("How long have you known {D}?", "\"Several years. We were close and spoke often by phone. I saw {DF} regularly at that time.\""), .direct("What did the defendant tell you about the illness?", "\"That there was a diagnosis and big bills and that a fundraiser would help. I took it at face value and did not ask for records.\""), .direct("Did you see any sign of illness?", "\"{D.He} sometimes seemed tired or achy, but looked fine when we went out. I never saw treatment, and I was not there for appointments.\""), .cross("Did you see any treatment?", "\"Unknown. I never saw one. I wasn't there for appointments.\""), .cross("Did you see records?", "\"No. Nothing. {D.He} didn't show me any.\""), .cross("Did you donate?", "\"A little. I'm not sure now whether it was right.\""), .cross("You never saw any hospital records, did you?", "\"No. {D.He} did not show me any, and I did not ask.\""), .cross("You gave to the fundraiser yourself, didn't you?", "\"A small amount, and I am no longer sure I wish I had.\"")],
        theory: ("{D} made up an illness.", "A real diagnosis."),
        allocution: "\"I should have been honest.\"",
        truths: ("{DL} bought a car the week after.", "The clinic note is real but undated."),
        defendant: [.direct("Do you have a rare illness?", "\"Yes. I have a real diagnosis. My records were lost when I changed doctors.\""), .direct("Why did you use photos from another account?", "\"I used pictures to illustrate the condition. I should have used my own. It was careless.\""), .direct("Did you mean to deceive donors?", "\"No. I needed help with costs. I told the truth about being ill.\""), .direct("What is your illness?", "\"A rare condition affecting my joints and nerves that took years to diagnose. I was seen by a clinic that gave me a note.\""), .direct("Why did you use photos from someone else?", "\"I did not have good photos of my own and borrowed hospital images from a similar patient. I should have said so.\""), .direct("How did you spend the money?", "\"On treatment, travel to appointments, and my bills. I also bought a used car to get to the clinic.\""), .cross("The hospital says it has no records, doesn't it?", "\"That's what they say. The records were lost. I showed a clinic note.\""), .cross("$27,000 is a lot of money, isn't it?", "\"It is. More than I expected. I used it for costs.\""), .cross("The photos belonged to someone else, didn't they?", "\"Yes. I'm sorry for that. It was a mistake.\""), .cross("You bought a car the week after the donations, didn't you?", "\"Yes, because I needed a car to reach the clinic. I know the timing looks bad.\""), .cross("The clinic note has no date on it, does it?", "\"No. It is a short note, and I know it is not much.\"")],
        openings: ("{D} posted a fundraiser claiming a rare illness, using photos from a stranger's account, and received $27,000. The hospital has no records for {D}. The State will present a donor and the records.", "Jurors will also see a clinic note, a diagnosis {D} says was real, and records that were lost, not invented. Listen closely to the witnesses."),
        closings: ("Photos from a stranger, no hospital records, and $27,000 from donors who believed. {D} took the money and bought a car the very next week.", "{D} says the diagnosis was real and the records were lost. The State has not proved {D} lied, and a clinic note and a friend's account suggest a person who was ill and clumsy with a fundraiser."),
        timeline: [(-10, "Page posted."), (0, "Donations pass $20,000."), (20, "Car bought."), (40, "A donor investigates.")],
        identified: "Fundraiser page.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let golfPartnerTips = SmallCases.make(
        key: "story.golfPartnerTips",
        category: .whiteCollar,
        headlines: ["Golf Partner Traded on Tips From an Executive Over Coffee", "Stock Jumped the Morning After a Merger Announcement"],
        law: "securitiesFraud",
        threshold: 7,
        spec: "Willfully traded securities on material nonpublic information, on or about {DATE}.",
        ages: 30...65,
        victim: false,
        summary: "{D} bought $75,000 of a company's stock on {DATE}, a day before a merger announcement. {DL} says the buy was a hunch. A golf partner, an executive, had mentioned the deal.",
        state: [E(.digital, 3, "Trade Records", "A large order the day before."), E(.digital, 3, "Texts", "'Big news soon.'"), E(.document, 2, "Gain Report", "$61,000 profit.")],
        defense: [E(.statement, 1, "Research Notes", "{DL} shows notes from earlier months.")],
        role: "Securities investigator",
        exam: [.direct("What did the trade records show?", "\"{D} bought $75,000 of a company's stock on {DATE}, a day before a merger announcement.\""), .direct("What did the texts say?", "\"One said, 'Big news soon.' The gain report shows a $61,000 profit after the announcement.\""), .direct("Why does that matter to you?", "\"It suggests {DL} traded on inside information, not a hunch. A golf partner, an executive, had mentioned the deal.\""), .direct("How does your office detect suspicious trades?", "\"We scan for large trades ahead of announcements, especially from accounts that never traded that stock. {D.his} buy was a standout.\""), .direct("What did you see in {D}'s account?", "\"A $75,000 purchase the day before the merger. It was the first time {DL} ever bought that company, and it doubled in value on the news.\""), .direct("What did the texts add?", "\"Two days earlier the executive texted, 'big news soon,' and {D.he} replied with a thumbs up. They also played golf that week.\""), .cross("{DL} says the buy was a hunch, doesn't {D.he}?", "\"There are research notes from earlier months. I can't say how much weight they carry.\""), .cross("Did the executive give {DL} specifics?", "\"I can't say. The executive says only small talk. I can't prove the deal was named.\""), .cross("Is a large buy before news always illegal?", "\"No. People buy on research and hunches. We look at timing and information.\""), .cross("The executive did not name the deal, did the executive?", "\"No. The executive says it was a casual remark.\""), .cross("{D} has research notes from months earlier, doesn't {D.he}?", "\"Yes, notes on the company, dated before the texts. They show interest, but they do not explain the timing.\"")],
        defenseRole: "Golf partner",
        defenseExam: [.direct("Do you play golf with {DL}?", "\"Yes. We play fairly often. We talk about everything.\""), .direct("What was said?", "\"Small talk. Work, family, nothing specific. I never gave any details.\""), .direct("Did you mention the merger?", "\"Not in any way I can recall. I'm careful about confidential matters.\""), .direct("How well do you know {D}?", "\"We have golfed together a couple of times a month for years. We talk about family and work and the usual things.\""), .direct("What did you say about the company?", "\"That things were busy and that there might be good news soon. I did not name a deal, and I would never share details.\""), .direct("What did you think when the defendant bought the stock?", "\"I was surprised when I read about it. I did not realize {D} was thinking of buying.\""), .cross("Was the deal named?", "\"No. Not by me. I would not have.\""), .cross("Did {DL} ask about the company?", "\"I don't remember. We talk casually. I can't swear to every word.\""), .cross("You did send a text saying big news soon, didn't you?", "\"Possibly. I say things like that all the time, and I did not mean it as a tip.\""), .cross("You work at the company that merged, don't you?", "\"Yes, as an executive. I know I should have been more careful.\""), .cross("You never told the defendant the name of the company, did you?", "\"I talked about work in general terms. I may have said big news was coming, but I did not name a company or a date.\"")],
        theory: ("{D} traded on a tip.", "Public research."),
        allocution: "\"I knew it was wrong.\"",
        truths: ("{DL} had never bought this stock.", "The notes predate the texts."),
        defendant: [.direct("Why did you buy that stock?", "\"I'd been researching the company for months. I had notes. I thought it was undervalued.\""), .direct("What about the golf partner?", "\"We played golf and talked about work. It was small talk. No deal was ever named.\""), .direct("Did you know of the merger?", "\"No. I had a hunch. I'm as surprised as anyone that it came when it did.\""), .direct("What research did you do?", "\"I read the company's reports for months and followed the industry. I wrote notes about a possible turnaround.\""), .direct("Why did you buy that day?", "\"I had saved up cash and thought the price was low. I also had a hunch the stock would move.\""), .direct("What did the golf partner say?", "\"Small talk about work, and that something good might be happening. I thought it was a general remark.\""), .cross("You bought $75,000 the day before the announcement, didn't you?", "\"Yes. It was a good day to buy. I had no inside information.\""), .cross("The text said 'big news soon,' didn't it?", "\"It did. I thought it was general. I didn't take it as a tip.\""), .cross("You made $61,000, didn't you?", "\"Yes. I got lucky. It looks suspicious, but I didn't trade on a tip.\""), .cross("You had never bought this stock before, had you?", "\"No, though I followed it. This was my first purchase.\""), .cross("You put in $75,000 one day before big news, didn't you?", "\"Yes. It looks like more than luck, and I understand why investigators asked.\"")],
        openings: ("{D} bought $75,000 of a company's stock the day before a merger announcement and made $61,000. A golf partner who is an executive had texted, 'Big news soon.' The State will present the securities investigator and the trades.", "The defense evidence includes months of research notes, a golf partner who only made small talk, and a buy that was a hunch. Listen closely to the witnesses."),
        closings: ("A $75,000 buy the day before a merger, a text about big news, and a $61,000 profit. That is trading on a tip.", "A hunch and a lucky day. The golf partner named no deal. The State has not proved {D} traded on inside information."),
        timeline: [(-30, "Golf round."), (-1, "The trade."), (0, "Merger announced."), (40, "Investigator calls.")],
        identified: "Trade records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let mowerOnTheBypass = SmallCases.make(
        key: "story.mowerOnTheBypass",
        category: .traffic,
        headlines: ["Driver Steers a Riding Mower Down the Bypass After a Night of Drinking"],
        law: "dwi",
        spec: "Operated a vehicle on a highway while impaired, on {DATE}.",
        ages: 21...65,
        victim: false,
        summary: "{D} rode a lawn mower down a four-lane bypass on {DATE} after drinking at a cookout. {D} was on the shoulder of the bypass at 7 p.m., and the trooper stopped the mower at 7:20 p.m. The bypass is a four-lane road with a posted speed limit.",
        state: [E(.video, 3, "Highway Camera", "{D} mows along the shoulder at dusk."), E(.statement, 2, "Trooper", "Stopped the mower on the shoulder at dusk.")],
        defense: [E(.statement, 1, "Short Trip", "{DL} says {D.he} was only going to a neighbor's.")],
        role: "Trooper",
        exam: [.direct("What did the highway camera show?", "\"It shows {D} riding a lawn mower along the shoulder of the bypass at dusk, at about 7 p.m.\""), .direct("What kind of road is the bypass?", "\"A four-lane road with a posted speed limit. The bypass is posted for vehicles, and a mower does not belong there.\""), .direct("What did you do?", "\"I stopped the mower on the shoulder at 7:20. {D.He} had a cooler on the mower, and I smelled alcohol.\""), .direct("How did you notice the mower?", "\"I was patrolling the bypass at about seven in the evening when a motorist called in a lawn mower on the shoulder. I found it near the second exit.\""), .direct("What did you see when you reached {D}?", "\"A riding mower with a drink cooler strapped on the back, moving about eight miles an hour. {D.He} smelled of alcohol and had glassy eyes.\""), .direct("What happened next?", "\"I stopped the mower, asked for ID, and did a field sobriety test. {D.He} could not complete it, and I took {D.him} into custody.\""), .cross("How far did the defendant ride on the bypass?", "\"About half a mile. {D.He} stayed on the shoulder the whole way.\""), .cross("Did the defendant cause any accidents?", "\"No. No one was hit, and no vehicle was forced off the road.\""), .cross("Was the defendant cooperative?", "\"Yes. {D.He} was polite and did not argue or try to get away.\""), .cross("{D} stayed on the shoulder, didn't {D.he}?", "\"Yes, the whole time, with the mower's lights on. A few trucks passed close, but none hit.\""), .cross("The bypass is posted for vehicles, isn't it?", "\"Yes. A mower does not meet the minimum speed, and it is not permitted.\"")],
        theory: ("{D} drove drunk on a bypass.", "A short trip."),
        allocution: "\"I'm sorry.\"",
        truths: ("The bypass was posted for vehicles.", "{DL} had a cooler on the mower."),
        defendant: [.direct("Why were you on the bypass with a mower?", "\"I took a shortcut home from a cookout. It seemed like the quickest way, and I did not think about the road.\""), .direct("Had you been drinking?", "\"Four drinks. I had been at a cookout for a few hours, and I thought I was fine.\""), .direct("How far were you going?", "\"About half a mile. I only meant to cover a short stretch before turning off.\""), .direct("What happened at the cookout?", "\"A friend hosted a cookout with burgers and drinks. I had about four beers over a few hours and rode my mower over because I live close.\""), .direct("Why the bypass?", "\"It was a shortcut across to my neighbor's farm. I only meant to go a half mile.\""), .direct("What did you think about the traffic?", "\"I thought the shoulder was wide enough, and I kept the mower's light on. I did not think about drivers who could not see me at dusk.\""), .cross("You rode a mower on a four-lane road at dusk after drinking, didn't you?", "\"Yes. I know how foolish that was. I did not think about the danger.\""), .cross("You had a cooler on the mower, didn't you?", "\"Yes. It was a drink cooler. I should not have had it.\""), .cross("Cars were doing highway speeds past you, weren't they?", "\"Yes. I was lucky no one was hurt.\""), .cross("You rode a mower on a four-lane bypass at dusk, didn't you?", "\"Yes, and I was lucky no one was hurt.\""), .cross("You could have taken the back road, couldn't you?", "\"Yes. It would have added ten minutes and I did not want to walk.\"")],
        openings: ("At dusk, a highway camera shows {D} riding a lawn mower with a cooler along the shoulder of a four-lane bypass after drinking at a cookout. A trooper stopped the mower twenty minutes later.", "The defense will present evidence that {D} took a half-mile shortcut, stayed on the shoulder, and hurt no one, and that this was foolish, not malicious."),
        closings: ("A lawn mower on a four-lane bypass at dusk, a cooler on board, and a driver who had been drinking. Cars passing at highway speed were at risk.", "A foolish half-mile shortcut on the shoulder with no harm done. {D} accepts it was a bad idea, and this calls for a modest response."),
        timeline: [(0, "7 p.m.: the mower."), (0, "7:20 p.m.: the stop.")],
        identified: "Highway Camera",
        mood: .indifferent)

    static let buriedCoinDig = SmallCases.make(
        key: "story.buriedCoinDig",
        category: .property,
        headlines: ["Treasure Hunter Dug Holes in a Farmer's Field"],
        law: "injuryRealProperty",
        spec: "Willfully injured the real property of {V}, on {DATE}.",
        ages: 18...70,
        victim: true,
        summary: "{D} dug a dozen holes in {V}'s field on {DATE} looking for a buried coin hoard. {D} began digging at 11 p.m., and the farmer arrived at midnight. A drain line in the field was broken.",
        state: [E(.video, 3, "Field Camera", "{D} digs near the fence line at night."), E(.document, 2, "Repair Estimate", "A repair estimate for the broken drain line.")],
        defense: [E(.statement, 1, "Permission", "{DL} says a worker said it was fine.")],
        role: "Landowner",
        exam: [.direct("What did you find in your field on {DATE}?", "\"A dozen holes dug across my field, and a drain line broken. The farmer arrived at midnight and found someone digging.\""), .direct("What does your field camera show?", "\"It shows {D} digging near the fence line at night, starting at about 11 p.m.\""), .direct("What is the field used for?", "\"I grow soybeans and corn on about forty acres. A drain line runs under the middle to move water off the low spots.\""), .direct("What did you see that night?", "\"A light bobbing near the fence line at about midnight. I walked out and found {D.him} with a shovel and a metal detector, standing in a hole.\""), .direct("What was the damage?", "\"About a dozen holes across the field, some three feet deep, and a broken clay drain tile. The repair estimate is for digging up and replacing a section.\""), .direct("What did you do when you found the holes in your field?", "\"I flagged each one and walked the drain line with a probe. The tile was cracked in one spot, and water was already pooling around the break.\""), .cross("{DL} says a worker said it was fine, doesn't {D.he}?", "\"I never gave permission, and I don't know who a worker would be.\""), .cross("Did {DL} take anything?", "\"No. I don't think anything was found. {D.He} dug looking for coins and found nothing.\""), .cross("Did {DL} try to hide?", "\"The camera shows {DL} digging in the open, at night. {DL} didn't run when I arrived.\""), .cross("{D} was not hiding when you arrived, was {D.he}?", "\"No. {D.He} stopped digging and explained what {D.he} was doing. {D.He} seemed embarrassed.\""), .cross("Nothing was found in the holes, was there?", "\"Not that I could see. {D.He} said nothing had turned up.\"")],
        theory: ("{D} dug without permission.", "A worker's okay."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} brought a metal detector at night.", "The worker is a teenager."),
        defendant: [.direct("Why were you digging in {V}'s field?", "\"I was looking for a buried coin hoard. I'd heard stories. A worker told me it was fine to dig.\""), .direct("Who gave you permission?", "\"A worker at the farm. I took that as permission. I didn't ask the owner.\""), .direct("Did you mean to break the drain?", "\"No. I didn't know it was there. I'm sorry for the damage.\""), .direct("How did you learn about the hoard?", "\"From an old local story about coins buried in that area in the 1800s. I researched it for months at the library.\""), .direct("How did you get permission?", "\"I stopped by the farm in the afternoon and spoke to a young worker in the yard. The worker shrugged and said go ahead.\""), .direct("Why at night?", "\"I work all day, and I thought the cool hours would be better. I used a headlamp and kept it low.\""), .cross("You dug a dozen holes at night, didn't you?", "\"Yes. It looks bad, I know. I wasn't hiding.\""), .cross("You didn't ask {V}, did you?", "\"No. I wish I had. I assumed the worker could say yes.\""), .cross("The drain line was broken, wasn't it?", "\"Yes. I'll pay for it. I never meant to damage anything.\""), .cross("You never asked the owner, did you?", "\"No. I assumed the worker had authority, and I now see how weak that assumption was.\""), .cross("You dug a dozen holes in a working field, didn't you?", "\"Yes. I filled some of them back in, but not all.\"")],
