        headlines: ["Contest Favorite's Giant Pumpkin Found Smashed"],
        law: "injuryPersonalProperty",
        spec: "Willfully injured the personal property of {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} smashed {V}'s 900-pound contest pumpkin before judging on {DATE}, costing {V.him} a $3,000 prize. The hammer came at midnight, and judging was at 9 a.m. The pumpkin weighed 900 pounds.",
        state: [E(.video, 3, "Barn Camera", "{D} swings a hammer."), E(.document, 2, "Contest Rules", "A $3,000 prize for the heaviest pumpkin.")],
        defense: [E(.statement, 1, "Rotten", "{DL} says it was already rotten.")],
        role: "Contest judge",
        exam: [.direct("What happened at the pumpkin contest on {DATE}?", "\"{V}'s 900-pound pumpkin was smashed at midnight, before judging at 9 a.m. {V} lost a chance at the $3,000 prize.\""), .direct("What does the barn camera show?", "\"It shows {D} swinging a hammer at the pumpkin. It shows the swings and the pumpkin splitting.\""), .direct("What are the contest rules?", "\"A $3,000 prize for the heaviest pumpkin. The pumpkin weighed 900 pounds and would have been in the running.\""), .direct("How does the contest work?", "\"Growers weigh in their pumpkins at nine in the morning, and the heaviest wins a $3,000 prize. The pumpkins are kept in a locked barn overnight.\""), .direct("What was special about {V}'s pumpkin?", "\"It weighed about 900 pounds in the weigh-in at the start of the fair, the heaviest of the field. It was a favorite to win.\""), .direct("What did you find that morning?", "\"The pumpkin was split open and mashed across the barn floor, with hammer marks in the rind. The camera showed {DL} swinging at midnight.\""), .cross("{DL} says it was already rotten, doesn't {D.he}?", "\"I examined it earlier. It looked sound, but I can't say how it was after midnight.\""), .cross("Could the pumpkin have won?", "\"Possibly. At 900 pounds, it was a contender. I can't say it would have won.\""), .cross("Did you see {DL} swing the hammer?", "\"Only on camera. I wasn't there at midnight.\""), .cross("The pumpkin could have been soft on one side, couldn't it?", "\"Giants often have soft spots. I examined it earlier and found it sound.\""), .cross("{D} entered a pumpkin of {D.his} own, didn't {D.he}?", "\"Yes, and it was smaller. It would have taken the prize with {V}'s out.\"")],
        theory: ("{D} smashed it.", "Already rotten."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} entered a rival pumpkin.", "The pumpkin was fresh."),
        defendant: [.direct("Why were you in the barn at midnight?", "\"I wanted to look at the pumpkins. I saw {V}'s was rotten. I hit it to see how deep it was.\""), .direct("Was it rotten?", "\"I believed so. It was soft on one side. I swung and it broke.\""), .direct("Did you mean to ruin {V}'s chance?", "\"No. I thought it was already ruined. I never meant to cost {V.him} the prize.\""), .direct("What was your own entry?", "\"A smaller pumpkin that weighed about 700 pounds. I grew it for two seasons and hoped for a ribbon.\""), .direct("What did you see in the barn?", "\"A giant pumpkin with a soft patch on one side and a sour smell. I thought it was already going bad.\""), .direct("How did you feel about the contest in the days before it?", "\"Tense. I had grown mine for months and worried it was not big enough. I was angry with myself, and I made a terrible decision.\""), .cross("You swung a hammer at a 900-pound pumpkin, didn't you?", "\"Yes. I did. It was a poor way to check.\""), .cross("The judging was at 9 a.m., wasn't it?", "\"Yes. I knew that. I should have said something to the judges instead.\""), .cross("The prize was $3,000, wasn't it?", "\"Yes. I'm so sorry. I'll pay if I need to.\""), .cross("You swung a hammer at it, didn't you?", "\"Yes. I thought I was putting a rotten thing out of its misery, and that was a poor way to do it.\""), .cross("Your pumpkin would have won without {V}'s, wouldn't it?", "\"Probably, and I know that looks suspicious. I did not do it for that.\"")],
        openings: ("At midnight, a barn camera caught {D} swinging a hammer at {V}'s 900-pound contest pumpkin, hours before judging for a $3,000 prize. The State will show the video and the rules.", "The defense will point you to a pumpkin that {D} believed was already rotten, and a person who had no reason to want {V} to lose. Listen closely to the witnesses."),
        closings: ("A hammer at midnight, a 900-pound pumpkin smashed, and judging at 9 a.m. {V} lost a $3,000 prize because someone chose to destroy the heaviest entry in a locked barn.", "{D} says the pumpkin was rotten and never meant to cost {V} a prize. The State has not proved {D} knew it was sound, and a soft spot on a giant pumpkin can look like trouble."),
        timeline: [(0, "midnight: hammer."), (0, "9 a.m.: judging.")],
        identified: "Barn Camera",
        mood: .indifferent)

    static let spotlightHunt = SmallCases.make(
        key: "story.spotlightHunt",
        category: .publicOrder,
        headlines: ["Hunters Shine Spotlights at Deer From a Truck at Night"],
        law: "misdLarceny",
        spec: "Took and carried away wildlife belonging to the State by spotlight at night, on {DATE}.",
        ages: 18...65,
        victim: false,
        summary: "{D} shot a deer from a truck window using a spotlight on {DATE}. The light came on at 10 p.m. and the shot followed five minutes later. The season was closed.",
        state: [E(.physical, 3, "Spotlight and Rifle", "Found in the truck bed."), E(.document, 2, "Season Booklet", "The booklet lists the season as closed.")],
        defense: [E(.statement, 1, "Out of Season", "{DL} says the season question was unclear.")],
        role: "Wildlife officer",
        exam: [.direct("What did you see on the night of the shooting?", "\"A spotlight came on at about 10 p.m., and five minutes later a shot followed. A deer was shot from a truck window.\""), .direct("What did you find in the truck bed?", "\"A spotlight and a rifle. Both were in the bed, and they matched what was used for the shot.\""), .direct("What about the season?", "\"It was closed. The season booklet lists the season as closed, and it was in the glove box of the truck.\""), .direct("How did you hear about it?", "\"A caller reported a spotlight and a gunshot on a county road at around ten at night. I drove out and found a pickup on the shoulder.\""), .direct("What did you find?", "\"A rifle in the truck bed, a spotlight plugged into the dash, and a fresh deer in the ditch. {D} was standing beside the truck.\""), .direct("What does the season booklet say?", "\"The deer season for that zone was closed for another two weeks. Night shooting with a light is never allowed.\""), .cross("Was it fully dark at 10 p.m.?", "\"Yes. It was night. The shot was at night.\""), .cross("{D} says the season was unclear, doesn't {D.he}?", "\"Yes. {D.He} says so. The booklet states it clearly, but I understand why it can be confusing.\""), .cross("Was the defendant cooperative?", "\"Yes. {D.He} was cooperative and showed me where the booklet was.\""), .cross("{D} told you where the deer was, didn't {D.he}?", "\"Yes, immediately. {D.He} walked me to it and handed over the rifle.\""), .cross("The booklet was in the glovebox, wasn't it?", "\"Yes, still in its plastic. It did not look like it had been opened.\"")],
        theory: ("{D} hunted illegally.", "A mistaken season."),
        allocution: "\"I'm sorry.\"",
        truths: ("The deer was shot at night.", "The booklet was in the glovebox."),
        defendant: [.direct("Did you shoot the deer?", "\"Yes, I did. I used a spotlight from the truck window, and I fired when I saw the deer.\""), .direct("Did you know the season was closed?", "\"It was unclear to me. I thought the season was still open, and I did not read it carefully.\""), .direct("Was it night when you shot?", "\"It was dusk to me, though it was dark. I know it was after the legal time.\""), .direct("What was your plan?", "\"I wanted venison for the freezer. A friend told me the season had opened, and I did not look it up.\""), .direct("How did you shoot?", "\"I put a spotlight on the deer from the truck and fired once. It dropped, and I got out to dress it.\""), .direct("What did you do when the officer arrived?", "\"I put the rifle down and showed where the deer was. I said I had done something wrong.\""), .cross("The booklet was in your glove box, wasn't it?", "\"Yes. I never read it. In hindsight, yes.\""), .cross("You used a spotlight, didn't you?", "\"Yes. It is illegal. I did not realize.\""), .cross("You shot from a truck window, didn't you?", "\"Yes. I know that is wrong. I was careless.\""), .cross("The spotlight is for hunting at night, isn't it?", "\"I know now it is illegal. I thought it only helped me see.\""), .cross("You never read the booklet, did you?", "\"No. I should have checked the dates before I went out.\"")],
        openings: ("At 10 p.m., {D} shot a deer from a truck window using a spotlight during a closed season. A wildlife officer found the spotlight and rifle in the bed, and the season booklet in the glove box said closed.", "The defense witnesses will explain that {D} was confused about the season, never read the booklet carefully, and cooperated fully with the officer."),
        closings: ("A spotlight, a rifle, a deer shot at night, and a booklet in the glove box that says the season was closed. {D} hunted illegally.", "{D} was confused about the season and cooperated with the officer. A careless misreading is not the same as a deliberate poaching."),
        timeline: [(0, "10 p.m.: the light."), (0, "10:05 p.m.: the shot.")],
        identified: "Spotlight and Rifle",
        mood: .indifferent)

    static let electionSignSabotage = SmallCases.make(
        key: "story.electionSignSabotage",
        category: .publicOrder,
        headlines: ["Driver Cuts Down Dozens of Campaign Signs"],
        law: "injuryPersonalProperty",
        spec: "Willfully injured the personal property of {V}, on {DATE}.",
        ages: 18...70,
        victim: true,
        summary: "{D} cut down 40 yard signs for {V}'s campaign on {DATE}, a loss of about $900. The cutting began at 6 a.m., and volunteers found the signs later that day. About forty signs were destroyed.",
        state: [E(.video, 3, "Truck Camera", "{D} slashes signs along the road."), E(.document, 2, "Sign Order", "An order for the campaign's yard signs.")],
        defense: [E(.statement, 1, "Misplaced", "{DL} says signs blocked the right of way.")],
        role: "Campaign volunteer",
        exam: [.direct("What did you find on {DATE}?", "\"About forty of {V}'s yard signs had been destroyed. Volunteers found them later that day, and the loss was about $900.\""), .direct("What does the sign order show?", "\"An order for the campaign's yard signs. That proves what they cost and how many we had.\""), .direct("How did you place the signs?", "\"Volunteers set them in yards of supporters along the county road, forty in all, each on a wire stake. We asked each homeowner before planting one.\""), .direct("What did you find that morning?", "\"Signs sliced in half or cut at the stake all along the road, with the pieces dropped in the ditch. A neighbor called me at eight.\""), .direct("What does the truck camera show?", "\"A pickup pulling along the shoulder at about six, and {D} stepping out with a hatchet and slashing sign after sign. It takes about twenty minutes.\""), .direct("What did the campaign do after the signs were found cut?", "\"We photographed every one, called the sheriff's office, and ordered replacements. The volunteers reset them the same night so the road was not left bare.\""), .cross("{DL} says signs blocked the right of way, doesn't {D.he}?", "\"I don't know that all of them did. Some were in front yards.\""), .cross("Did you ask {DL} to move any?", "\"No. No one contacted us. We'd have moved any that were a problem.\""), .cross("Did {DL} take the signs?", "\"Slashed, not taken. The camera shows the cutting.\""), .cross("Some signs were close to the road, weren't they?", "\"A few were near the edge of a yard. All stood on the owners' lots with permission.\""), .cross("Signs for other candidates were left alone, weren't they?", "\"Yes. Only our signs were cut, which is what makes it look targeted.\"")],
        theory: ("{D} cut the signs.", "Right of way."),
        allocution: "\"I'm sorry.\"",
        truths: ("Signs were on private land.", "{DL} cut only one candidate's."),
        defendant: [.direct("Why did you cut the signs?", "\"They were blocking the road's right of way. I thought they were a safety problem, and I cut them down.\""), .direct("Did you cut only {V}'s signs?", "\"I cut the ones I thought were in the way. I didn't pick a candidate. I thought I was cleaning up.\""), .direct("Did you intend to hurt the campaign?", "\"No. I had no reason to. I thought I was doing the right thing.\""), .direct("What did you see on the road?", "\"A long line of yard signs close to the road edge near a curve. I was worried they blocked the view for drivers.\""), .direct("Why did you cut them?", "\"I thought they were in the county's right of way and creating a hazard. I took a hatchet from my truck and cut the ones I thought were too close.\""), .direct("Did you check whose land they were on?", "\"No. I assumed they were on the shoulder. I did not look at the property lines.\""), .cross("You cut forty signs, didn't you?", "\"Yes. About that many. It was a lot.\""), .cross("You started at 6 a.m., didn't you?", "\"Yes. Early, before traffic. I wasn't hiding.\""), .cross("You never called the county, did you?", "\"No. In hindsight, yes. I took it into my own hands.\""), .cross("You cut only one candidate's signs, didn't you?", "\"Yes, because those were the ones in that stretch. I did not walk the rest of the road.\""), .cross("You did not contact the county or the campaign, did you?", "\"No. I made the call myself, and it was a poor one.\"")],
        openings: ("At 6 a.m., a truck camera caught {D} slashing about forty of {V}'s campaign yard signs, a $900 loss. The State will present a campaign volunteer, the video, and the sign order.", "Jurors will also see a person who believed the signs blocked the right of way, who cut them in the open, and who had no stake in the race."),
        closings: ("Forty campaign signs slashed along the road, on camera, and a campaign out $900. Cutting down one side's signs while leaving the rest is not about a right of way.", "{D} believed the signs blocked the right of way. The State has not proved {D} meant to harm a campaign, and a person who acts in the open at dawn is not hiding an agenda."),
        timeline: [(0, "6 a.m.: the cutting."), (1, "Volunteers find the signs.")],
        identified: "Truck Camera",
        mood: .indifferent)

    static let oysterBedPoach = SmallCases.make(
        key: "story.oysterBedPoach",
        category: .property,
        headlines: ["Boater Cited for Harvesting Oysters From a Closed Bed"],
        law: "misdLarceny",
        spec: "Took and carried away property of the State, on {DATE}.",
        ages: 18...65,
        victim: false,
        summary: "{D} harvested oysters from a closed bed on {DATE} and sold them at a dock. The marine patrol was on the water at dawn and seized the catch the same morning. The bed had been posted closed for weeks before the harvest.",
        state: [E(.physical, 3, "Oyster Sacks", "Forty sacks aboard."), E(.document, 2, "Closure Notice", "The bed was posted closed.")],
        defense: [E(.statement, 1, "Boundary", "{DL} says the markers had drifted.")],
        role: "Marine patrol officer",
        exam: [.direct("What did you find on the water at dawn?", "\"{D}'s boat, loaded with forty sacks of oysters. They had been harvested from a bed that was closed.\""), .direct("How was the bed marked?", "\"The bed had been posted closed for weeks. A closure notice was posted, and markers showed the boundary.\""), .direct("What did you do with the catch?", "\"We seized it the same morning. {D.He} had sold some at a dock at night.\""), .direct("What was the status of the oyster bed?", "\"It had been closed for weeks because of high bacteria counts after a storm. We posted signs and set boundary markers around it.\""), .direct("What did you see at dawn?", "\"{D.his} boat was anchored inside the closed area with oyster tongs in the water. We boarded and counted forty sacks on deck.\""), .direct("What did you learn about sales?", "\"{D.He} had already sold a load at a dock the night before, to buyers who did not ask where the oysters came from.\""), .cross("{D} says a marker drifted, doesn't {D.he}?", "\"Yes. Markers can drift. I will agree that sometimes they do.\""), .cross("Were the markers checked that week?", "\"Yes. They were checked that week, and they were in place.\""), .cross("Did the defendant resist the seizure?", "\"No. {D.He} cooperated. {D.He} did not argue.\""), .cross("Markers can shift in a storm, can't they?", "\"Yes. We checked them that week and found them in place.\""), .cross("{D} was fishing near the boundary, wasn't {D.he}?", "\"Yes, within about fifty yards of the line. The boat was inside it.\"")],
        theory: ("{D} took oysters illegally.", "A drifting marker."),
        allocution: "\"I'm sorry.\"",
        truths: ("The markers were checked that week.", "{DL} sold at night."),
        defendant: [.direct("Did you harvest from a closed bed?", "\"I did, but I thought I was in an open bed. A marker had drifted, and I followed it.\""), .direct("Where did you sell the oysters?", "\"At the dock. I sold them openly at the dock, like I always do.\""), .direct("Who checked the markers?", "\"I did. I checked them when I went out, and I believed they were right.\""), .direct("How long have you worked these waters?", "\"Twenty years. I know where the beds are and where the lines are drawn.\""), .direct("What did you think about the closure?", "\"I thought it ended at the next marker over, a little north of where I worked. A marker looked like it had drifted.\""), .direct("What did you do when marine patrol arrived?", "\"I hauled up my gear and let them look at the catch. I told them where I had been working.\""), .cross("Forty sacks is a lot of oysters. Isn't that a big harvest for an honest mistake?", "\"It is a lot. I was working a long run.\""), .cross("You sold at night, didn't you?", "\"Yes. That is when buyers come. It is not unusual.\""), .cross("You sold oysters at night, didn't you?", "\"Yes, because that is when the buyers come. It is normal, but I know it looks bad.\""), .cross("The bed had been closed for weeks, hadn't it?", "\"Yes, and I knew. I thought I was in an open part, and I was wrong.\""), .cross("You knew the bed was posted closed when you set out that morning, didn't you?", "\"I knew about the closure notice, yes. I thought the markers had drifted and that I was inside the open line, and I did not check.\"")],
        openings: ("A marine patrol officer found {D}'s boat at dawn with forty sacks of oysters taken from a bed that had been posted closed for weeks. {D} had already sold some at a dock the night before.", "The defense case is that a marker drifted, that {D} believed the harvest was in an open bed, and that {D} sold openly at the dock."),
        closings: ("A closed bed, posted for weeks, forty sacks aboard, and oysters already sold at night. {D} knew where the closed water was, and harvested anyway.", "A drifting marker and a waterman who honestly believed {D.his} location was legal. The State must prove {D} knew the bed was closed, and a drifted marker raises doubt."),
        timeline: [(0, "dawn: patrol."), (0, "dawn: seizure.")],
        identified: "Oyster Sacks",
        mood: .indifferent)

    static let rodeoClownShove = SmallCases.make(
        key: "story.rodeoClownShove",
        category: .violent,
        headlines: ["Rodeo Clown Shoves a Heckler in the Stands"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 20...55,
        victim: true,
        summary: "{D}, dressed as a rodeo clown, shoved a heckler in the stands on {DATE}. The heckle came at 9 p.m., and the shove followed five minutes later. {V} fell a couple of rows.",
        state: [E(.video, 3, "Arena Video", "{D} climbs the rail and pushes {V}."), E(.document, 2, "Medical Note", "A bruise from the fall.")],
        defense: [E(.statement, 1, "Provoked", "{DL} says {V} threw a drink.")],
        role: "Arena guard",
        exam: [.direct("What did you see in the arena?", "\"{D}, dressed as a rodeo clown, climbed a rail and pushed {V}, a heckler, in the stands at about 9:05 p.m.\""), .direct("What was the result of the shove?", "\"{V} fell down two rows of seats. A medical note records a bruise from the fall.\""), .direct("What is the clown's job at a rodeo?", "\"To distract bulls from fallen riders and keep the arena safe. Clowns are also expected to entertain the crowd and not engage with hecklers.\""), .direct("What happened before the shove?", "\"Someone in the third row shouted insults at {DL} for several minutes. {DL} walked to the rail and shouted back.\""), .direct("What did you see {D} do?", "\"{D.He} climbed over the rail, stepped into the stands, and shoved {V} backward. {V} fell down two rows of seats and hit a rail.\""), .direct("What does the rodeo do when someone in the stands is hurt?", "\"A medic comes to the rail, the show pauses, and a report is taken. {V} was checked and walked to the first-aid tent.\""), .cross("Did the defendant leave the ring right away?", "\"No. {D.He} did not return to the ring right away. {D.He} stayed to argue.\""), .cross("Was the defendant drinking?", "\"I smelled alcohol. I cannot say how much {DL} had.\""), .cross("Was {V} seriously hurt?", "\"No. {V} had a bruise. It could have been worse.\""), .cross("{V} threw a drink at the defendant first, didn't {V.he}?", "\"I saw a cup fly, but I could not tell who threw it. There was beer on the arena floor afterward.\""), .cross("{D} returned to the ring afterward, didn't {D.he}?", "\"Eventually, after about ten minutes. I walked {D.him} out of the stands first.\"")],
        theory: ("{D} shoved a fan.", "Provoked."),
        allocution: "\"I'm sorry.\"",
        truths: ("{V} fell down two rows.", "{DL} did not leave the ring."),
        defendant: [.direct("Did you shove {V} in the stands?", "\"Yes, I did. {V} had been heckling me for several minutes, and I lost my temper and pushed.\""), .direct("Had you been drinking before the rodeo night?", "\"Yes. I had a drink earlier. I should not have, and I let it get to me when I was heckled.\""), .direct("Did you return to the ring right away after that?", "\"No. I stayed in the stands a bit longer than I should have, yes. I was embarrassed and angry.\""), .direct("How was the night going?", "\"Loud and rowdy. I had been performing for three hours, and a heckler kept shouting about my makeup.\""), .direct("What did you do?", "\"I walked to the rail and said something sharp. A cup of beer hit my chest, and I climbed the rail and pushed the person I thought threw it.\""), .direct("How did it end?", "\"I pushed once, and the person fell back down two rows. I froze, then climbed back and left.\""), .cross("You climbed a rail to push someone in the stands, didn't you?", "\"Yes, I did. I know that is wrong. I let it happen, and I should have walked away.\""), .cross("{V} fell down two rows. Do you regret that?", "\"Yes. I am sorry for it. I did not mean for {V.him} to fall that far.\""), .cross("You are supposed to keep people safe at a rodeo, aren't you?", "\"Yes. As a clown, I am there to protect riders and fans. I let people down that night.\""), .cross("You are supposed to stay in the ring, aren't you?", "\"Yes. It is part of the job, and I left it.\""), .cross("You do not know who threw the cup, do you?", "\"I thought it was {V}. I am not sure now.\"")],
        openings: ("At 9 p.m., a heckler shouted at {D}, a rodeo clown, and five minutes later {D} climbed a rail and shoved {V} in the stands. {V} fell two rows, and the arena video shows it.", "Weigh the defense proof, which will show that {V} heckled {D} for several minutes and that {D} lost a temper once, with a minor bruise as the result."),
        closings: ("A clown climbs a rail, shoves a heckler, and the heckler falls two rows. The arena video shows it, and {D} had been drinking.", "A heckled entertainer who lost a temper in a moment. {V} had a bruise, and the State asks for more than this shove deserves."),
        timeline: [(0, "9 p.m.: the heckle."), (0, "9:05 p.m.: the shove.")],
        identified: "Arena Video",
        mood: .indifferent)

    static let plowChaseLot = SmallCases.make(
        key: "story.plowChaseLot",
        category: .traffic,
        headlines: ["Snowplow Driver Chases a Car Through a Parking Lot"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights of others, on {DATE}.",
        ages: 21...65,
        victim: false,
        summary: "{D} chased a car through a lot with a snowplow on {DATE} after a dispute over a spot. The chase began at 5 a.m., and deputies arrived ten minutes later. The sedan's bumper was damaged.",
        state: [E(.video, 3, "Lot Camera", "{D} chases a sedan."), E(.document, 2, "Repair Estimate", "A damaged bumper on the sedan.")],
        defense: [E(.statement, 1, "Dispute", "{DL} says the driver blocked the route.")],
        role: "Deputy",
        exam: [.direct("What did the lot camera show?", "\"It shows {D} chasing a sedan through a lot with a snowplow at about 5 a.m. The blade was down.\""), .direct("How did the chase end?", "\"Deputies arrived about ten minutes later. The sedan's bumper was damaged.\""), .direct("What did you learn about the dispute?", "\"It started over a parking spot. The sedan was parked legally.\""), .direct("How did you receive the call?", "\"A caller at the lot reported a snowplow chasing a car at about five in the morning. I arrived about ten minutes later.\""), .direct("What did the camera show?", "\"A plow with the blade down chasing a sedan around the lot, hitting its bumper twice. The sedan tried to leave and the plow cut off the exit.\""), .direct("What condition was the sedan in?", "\"The rear bumper was dented and cracked from two hits. The driver was shaken but not hurt.\""), .cross("{D} says the sedan blocked the route, doesn't {D.he}?", "\"Yes. {D.He} says the sedan was in the way. It was parked in a legal spot.\""), .cross("Did the plow hit the sedan hard?", "\"The bumper was damaged. It looks like the blade was used like a ram.\""), .cross("Was anyone hurt?", "\"No. No one was hurt, but a driver could have been.\""), .cross("The plow was working that morning, wasn't it?", "\"Yes, {D.he} was contracted to clear the lot. It had snowed overnight.\""), .cross("The sedan was parked in a marked space, wasn't it?", "\"Yes, a legal space near the entrance.\"")],
        theory: ("{D} chased a car.", "A blocked route."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} used the blade like a ram.", "The sedan was parked legally."),
